.modal-footer {
	display: flex;
	flex-wrap: wrap;
	justify-content: flex-end;
	align-items: flex-start;
	margin-top: -10px;
	/* Counteract the top margin of buttons */
	padding-top: 5px;
}

.modal-footer .btn-sm {
	margin-top: 10px;
	/* Add top margin to all buttons */
	margin-left: 5px;
	/* Maintain horizontal spacing */
}

.modal-footer::after {
	display: none;
}

.longPressOverlay {
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	bottom: 0;
	background-color: rgba(0, 0, 0, 0.3);
	backdrop-filter: blur(8px);
