/* bottom-sheet style Bootstrap modals on mobile — slide up from the bottom edge
   instead of the default fade/zoom-from-center */
@media (max-width: 767px) {
	.modal.fade .modal-dialog {
		transform: translate(0, 100%);
		transition: transform 220ms cubic-bezier(0.2, 0, 0.2, 1);
	}
	/* .in is Bootstrap 3's shown-state class and .show is Bootstrap 5's. Both
	   are listed because this file ships in both bundles, and matching only
	   one leaves the sheet parked at translate(0, 100%) -- a dialog-height
	   below the screen, with nothing but the backdrop visible. */
	.modal.in .modal-dialog,
	.modal.show .modal-dialog {
		transform: translate(0, 0);
	}
	.modal-dialog {
		position: fixed;
		bottom: 0;
		left: 0;
		right: 0;
		margin: 0;
		width: 100%;
		max-width: 100%;
	}
	.modal-content {
		border-radius: 12px 12px 0 0;
		border-bottom-left-radius: 0;
		border-bottom-right-radius: 0;
	}
}

/* HTMX loading indicator — thin sliding bar at very top while a request is in flight */
#gio-progress-bar {
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	height: 3px;
	background: linear-gradient(90deg, rgba(74, 144, 226, 0) 0%, rgba(74, 144, 226, 1) 50%, rgba(74, 144, 226, 0) 100%);
	background-size: 40% 100%;
	background-repeat: no-repeat;
	z-index: 2000;
	opacity: 0;
	pointer-events: none;
	transition: opacity 120ms ease-out;
}
#gio-progress-bar.active {
	opacity: 1;
	animation: gio-progress-slide 1.1s linear infinite;
}
@keyframes gio-progress-slide {
	0%   { background-position: -40% 0; }
	100% { background-position: 140% 0; }
}

/* page-transition fade-in on HTMX partial swaps (mobile/tablet only) */
@media (max-width: 991.98px) {
	#maincontent-refresh.gio-fade-in {
		animation: maincontent-fade-in 140ms ease-out;
	}
	@keyframes maincontent-fade-in {
		from { opacity: 0.35; }
		to   { opacity: 1; }
	}
}

