	width: 100%;
	/* = 100% - 2*5% padding */
}

.singlephoto-mytable {
	display: table;
	width: 100%;
	height: 100%;
}

.singlephoto-table-cell {
	display: table-cell;
	vertical-align: middle;
}

.singlephoto-table-cell a {
	color: white;
	display: block;
	min-height: 100%;
	width: 100%;
}

/*  For responsive images */
.singlephoto-mycontent .rs {
	width: auto;
	height: auto;
	max-height: 90%;
	max-width: 100%;
}

/*  For responsive images as background */
.singlephoto-bg {
	background-position: center center;
	background-repeat: no-repeat;
	background-size: contain;
	/* you change this to "contain" if you don't want the images to be cropped */
}

/* edit wiki page */
.wikiphoto-modal-body {
	max-height: calc(100vh - 212px);
	overflow-y: auto;
}

.wikiphoto-square {
	float: left;
	position: relative;
	width: 30%;
	padding-bottom: 30%;
	/* = width for a 1:1 aspect ratio */
	margin: 1.66%;
	background-position: center center;
	background-repeat: no-repeat;
	background-size: cover;
	/* you change this to "contain" if you don't want the images to be cropped */
	border: 4px solid #ffffff;
}

.wikiphoto-selected {
	border: 4px solid #668eaa;
}

/* group home */
.grouphome-fit {
	max-width: 100%;
	max-height: 100%;
}

/* Desktop group-home section cards: each h4-led block (Group
   Information / Settings / Email Addresses / Integrations / Top
   Hashtags / Archived Messages / Subscription) sits in a subtle card
   so the page reads as grouped sections instead of one long flow. */
.grouphome-card {
	background: #fff;
	border: 1px solid #e5e8ec;
	border-radius: 8px;
	padding: 16px 20px;
	margin-bottom: 16px;
}
.grouphome-card > h4:first-child {
	margin-top: 0;
	margin-bottom: 12px;
	padding-bottom: 10px;
	border-bottom: 1px solid #eee;
	font-weight: 600;
}
body.dark-mode .grouphome-card {
	background: var(--dark-mode-primary-color);
	border-color: var(--dark-mode-divider);
}
body.dark-mode .grouphome-card > h4:first-child {
	border-bottom-color: var(--dark-mode-divider);
}

/* Inside each card: tighten the list typography, soften the icon
   colour (icons are decoration, not emphasis), and add subtle row
   spacing so items read as distinct entries instead of a wall. */
.grouphome-card ul.list-unstyled {
	margin-bottom: 0;
}
.grouphome-card ul.list-unstyled > li {
	padding: 6px 0;
	line-height: 1.5;
}
.grouphome-card ul.list-unstyled > li + li {
	border-top: 1px solid #f0f2f5;
}
.grouphome-card ul.list-unstyled > li > i.fa-fw {
	color: #8891a0;
	margin-right: 6px;
}
body.dark-mode .grouphome-card ul.list-unstyled > li + li {
	border-top-color: var(--dark-mode-divider);
}
body.dark-mode .grouphome-card ul.list-unstyled > li > i.fa-fw {
	color: #7a8390;
}

/* Group Email Addresses: two-column label/value grid so long emails
   don't wrap under their labels. Labels are muted; values are the
   actionable mailto links. */
.grouphome-email-list {
	display: grid;
	grid-template-columns: auto 1fr;
	column-gap: 14px;
	row-gap: 8px;
	margin: 0;
}
.grouphome-email-list dt {
	color: #6b7380;
	font-weight: 500;
	align-self: baseline;
	white-space: nowrap;
}
.grouphome-email-list dd {
	margin: 0;
	word-break: break-all;
}
body.dark-mode .grouphome-email-list dt {
	color: var(--dark-mode-light-text-color, #98a1ae);
}

/* Top Hashtags: flex-wrap grid of chips with the thread count baked
   in as a subtle secondary number inside each chip. Replaces the old
   vertical list-per-row layout. */
.grouphome-tags-list {
	display: flex;
	flex-wrap: wrap;
	gap: 6px;
}
.grouphome-tag-chip {
	display: inline-flex;
	align-items: center;
	gap: 6px;
	padding: 4px 10px;
	border-radius: 14px;
	font-size: 13px;
	line-height: 1.3;
	text-decoration: none;
}
.grouphome-tag-chip:hover,
.grouphome-tag-chip:focus {
	filter: brightness(0.92);
	text-decoration: none;
}
.grouphome-tag-count {
	font-size: 11px;
	font-weight: 600;
	opacity: 0.85;
	padding: 1px 6px;
	background: rgba(0, 0, 0, 0.22);
	border-radius: 10px;
}

.grouphome-center {
	display: block;
	margin: auto;
}

/* Group home mobile cover hero: shallow 3:1 banner that bleeds
   edge-to-edge under the fixed navbar. The cover image is rendered
   at object-fit: contain so the full photo shows without cropping;
   off-aspect uploads letterbox with the page background. Mobile
   only — desktop uses the original centred .grouphome-fit image
   markup. */
.grouphome-hero {
	/* Bleed edge-to-edge on xs: counter the maincontent column's 5px
	   horizontal padding and cross the 5px gap that #maincontent
	   leaves under the fixed navbar so the image sits flush. */
	margin-left: -5px;
	margin-right: -5px;
	margin-top: -5px;
	position: relative;
	width: auto;
	aspect-ratio: 3 / 1;
	overflow: hidden;
	margin-bottom: 14px;
}
.grouphome-hero-img {
	position: relative;
	width: 100%;
	height: 100%;
	object-fit: contain;
	display: block;
}

/* group home mobile compact stats row: single-line member/topic/date
   summary between the hero and the tiles. */
.grouphome-stats {
	font-size: 13px;
	color: #707070;
	padding: 0 4px 10px;
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 0;
}
.grouphome-stat {
	white-space: nowrap;
}
.grouphome-stat i {
	margin-right: 3px;
}
.grouphome-stat-sep {
	color: #c8c8c8;
	margin: 0 6px;
}
body.dark-mode .grouphome-stats {
	color: var(--dark-mode-light-text-color);
}
body.dark-mode .grouphome-stat-sep {
	color: #555;
}

/* group home mobile hashtag chips: compact chip row, no counts. */
.grouphome-hashtags {
	margin: 14px 0 18px;
}
.grouphome-hashtags-head {
	display: flex;
	justify-content: space-between;
	align-items: baseline;
	font-size: 13px;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: 0.04em;
	color: #555;
	margin-bottom: 6px;
	padding: 0 4px;
}
.grouphome-hashtags-head a {
	font-size: 12px;
	font-weight: 400;
	text-transform: none;
	letter-spacing: 0;
}
.grouphome-hashtag-chip {
	display: inline-block;
	margin: 4px 4px 0 0;
	padding: 4px 10px;
	font-size: 13px;
	border-radius: 14px;
}
body.dark-mode .grouphome-hashtags-head {
	color: var(--dark-mode-light-text-color);
}

/* group home mobile tile grid: 4 compact square tiles per row.
   Overrides Bootstrap's .row negative margin to match the tighter
   per-tile column padding used below. */
.grouphome-tiles {
	margin: 12px -4px 18px;
}

/* group home mobile list (alternate layout; not currently rendered but
   retained for easy toggling from the tile grid). */
.grouphome-list {
	margin: 12px 0 18px;
	background: #fff;
	border-radius: 10px;
	overflow: hidden;
	box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
}
body.dark-mode .grouphome-list {
	background: var(--dark-mode-primary-color);
	box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}
.grouphome-row {
	display: flex;
	align-items: center;
	padding: 13px 14px;
	color: #333;
	text-decoration: none !important;
	border-top: 1px solid #eee;
	min-height: 48px;
}
.grouphome-row:first-child {
	border-top: 0;
}
.grouphome-row:hover,
.grouphome-row:focus,
.grouphome-row:active {
	background: #f2f5f9;
	color: #333;
}
body.dark-mode .grouphome-row {
	color: var(--dark-mode-text-color);
	border-top-color: var(--dark-mode-divider);
}
body.dark-mode .grouphome-row:hover,
body.dark-mode .grouphome-row:focus,
body.dark-mode .grouphome-row:active {
	background: var(--dark-mode-highlight-color);
	color: var(--dark-mode-text-color);
}
.grouphome-row-icon {
	font-size: 18px;
	color: #337ab7;
	margin-right: 14px;
	width: 22px;
	text-align: center;
}
body.dark-mode .grouphome-row-icon {
	color: #8cb4df;
}
.grouphome-row-label {
	flex: 1;
	font-size: 16px;
	font-weight: 500;
}
.grouphome-row-badge {
	background: #d9534f;
	color: #fff;
	padding: 1px 8px;
	border-radius: 10px;
	font-size: 12px;
	font-weight: 700;
	margin-left: 8px;
	min-width: 20px;
	text-align: center;
}
.grouphome-row-chevron {
	font-size: 12px;
	color: #c0c4ca;
	margin-left: 10px;
}
body.dark-mode .grouphome-row-chevron {
	color: #5a5e65;
}

/* Ensure no content hides behind the fixed bottom nav on the group
   home. The global #maincontent-column has padding-bottom:100px, but
   grouphome's body-height JS can reduce available space; add a little
   breathing room here on xs so the last visible element clears the
   nav + safe-area inset comfortably. */
@media (max-width: 767px) {
	#maincontent-column {
		padding-bottom: calc(110px + env(safe-area-inset-bottom));
	}
}

.grouphome-tile-col {
	padding-left: 4px;
	padding-right: 4px;
	margin-bottom: 8px;
}

.grouphome-tile {
	display: flex;
	flex-direction: column;
	justify-content: center;
	align-items: center;
	padding: 10px 4px;
	text-align: center;
	background-color: #f5f5f5;
	color: #333;
	border-radius: 8px;
	text-decoration: none;
	position: relative;
	min-height: 74px;
}

.grouphome-tile:hover,
.grouphome-tile:focus,
.grouphome-tile:active {
	background-color: #e8e8e8;
	color: #333;
	text-decoration: none;
}

.grouphome-tile i {
	font-size: 20px;
	display: block;
	margin-bottom: 6px;
	color: #337ab7;
}

body.dark-mode .grouphome-tile i {
	color: #8cb4df;
}

.grouphome-tile-label {
	font-size: 12px;
	display: block;
	line-height: 1.2;
}

.grouphome-tile-badge {
	position: absolute;
	top: 4px;
	right: 6px;
	background-color: #d9534f;
	color: #fff;
	padding: 1px 6px;
	border-radius: 10px;
	font-size: 11px;
	font-weight: bold;
	min-width: 18px;
}

body.dark-mode .grouphome-tile {
	background-color: var(--dark-mode-primary-color);
	color: var(--dark-mode-text-color);
}

body.dark-mode .grouphome-tile:hover,
body.dark-mode .grouphome-tile:focus,
body.dark-mode .grouphome-tile:active {
	background-color: var(--dark-mode-highlight-color);
	color: var(--dark-mode-text-color);
}

/* Group home description: clamp long descriptions with a fade-out
   gradient and a "Show more" toggle. JS unhides the button only when
   the content actually overflows the clamp. */
.grouphome-desc-wrap {
	position: relative;
	margin-bottom: 12px;
}
.grouphome-desc {
	position: relative;
}
.grouphome-desc.clipped {
	max-height: 160px;
	overflow: hidden;
}
.grouphome-desc.clipped::after {
	content: "";
	position: absolute;
	left: 0;
	right: 0;
	bottom: 0;
	height: 48px;
	pointer-events: none;
	background: linear-gradient(to bottom, rgba(255, 255, 255, 0), #fff);
}
body.dark-mode .grouphome-desc.clipped::after {
	background: linear-gradient(to bottom, rgba(0, 0, 0, 0), var(--dark-mode-body-color));
}
.grouphome-desc.expanded {
	max-height: none;
	overflow: visible;
}
.grouphome-desc.expanded::after {
	display: none;
}
.grouphome-desc-toggle {
	background: none;
	border: 0;
	padding: 4px 0;
	color: #337ab7;
	font-weight: 500;
	cursor: pointer;
}
.grouphome-desc-toggle[hidden] {
	display: none;
}
body.dark-mode .grouphome-desc-toggle {
	color: #8cb4df;
}
.grouphome-desc-toggle .grouphome-desc-less,
.grouphome-desc.expanded ~ .grouphome-desc-toggle .grouphome-desc-more {
	display: none;
}
.grouphome-desc.expanded ~ .grouphome-desc-toggle .grouphome-desc-less {
	display: inline;
}

/* Recent Topics list on the group home page. Compact rows with the
   subject on the left and a short relative-time tag on the right. */
.grouphome-recent {
	margin-top: 16px;
	margin-bottom: 16px;
}
.grouphome-recent-head {
	display: flex;
	align-items: baseline;
	justify-content: space-between;
	margin-bottom: 6px;
}
.grouphome-recent-title {
	margin: 0;
	font-size: 16px;
	font-weight: 600;
}
.grouphome-recent-title i {
	margin-right: 6px;
	color: #337ab7;
}
body.dark-mode .grouphome-recent-title i {
	color: #8cb4df;
}
.grouphome-recent-link {
	font-size: 12px;
	text-transform: uppercase;
	letter-spacing: 0.5px;
}
.grouphome-recent-list {
	list-style: none;
	padding: 0;
	margin: 0;
}
.grouphome-recent-item {
	display: flex;
	align-items: baseline;
	gap: 10px;
	padding: 4px 0;
	border-top: 1px solid #eee;
}
.grouphome-recent-item:first-child {
	border-top: 0;
}
body.dark-mode .grouphome-recent-item {
	border-top-color: var(--dark-mode-divider);
}
.grouphome-recent-subject {
	flex: 1 1 auto;
	min-width: 0;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.grouphome-recent-meta {
	flex: 0 0 auto;
	font-size: 12px;
	color: #777;
	white-space: nowrap;
}
body.dark-mode .grouphome-recent-meta {
	color: var(--dark-mode-muted-color, #999);
}

/* /groups mobile layout: compact list with page title, filter, and
   sort dropdown at the top. Desktop still renders the striped table. */
.groupslist-mobheader {
	padding: 8px 0 10px;
}
.groupslist-mobtitle {
	margin: 0 0 10px;
	font-size: 20px;
	font-weight: 600;
	color: #333;
}
body.dark-mode .groupslist-mobtitle {
	color: var(--dark-mode-text-color);
}
.groupslist-mobctrls {
	display: flex;
	gap: 8px;
	align-items: stretch;
}
.groupslist-mobfilter {
	position: relative;
	flex: 1;
}
.groupslist-mobfilter-icon {
	position: absolute;
	top: 8px;
	left: 10px;
	color: #999;
	pointer-events: none;
}
.groupslist-mobfilter input {
	padding-left: 28px;
}
.groupslist-mobsort .btn {
	white-space: nowrap;
}

/* Mobile-only row overrides for the groups table. */
@media (max-width: 767px) {
	#records.table-striped > tbody > tr > td,
	#records.table-striped > tbody > tr > th,
	#records.table-striped > tbody > tr {
		background-color: transparent;
	}
	#records > tbody > tr > td.groupslist-mobcell {
		border-top: 1px solid #eee;
		padding: 10px 0;
	}
	#records > tbody > tr:first-child > td.groupslist-mobcell {
		border-top: 0;
	}
	body.dark-mode #records > tbody > tr > td.groupslist-mobcell {
		border-top-color: var(--dark-mode-divider, #2b2b2b);
	}
}

.groupslist-mobcell {
	white-space: normal;
}
.groupslist-mobrow {
	display: flex;
	align-items: flex-start;
	gap: 12px;
}
.groupslist-mobicon-wrap {
	position: relative;
	flex: 0 0 56px;
}
.groupslist-mobicon {
	width: 56px;
	height: 56px;
	display: block;
}
.groupslist-mobunread {
	position: absolute;
	top: -4px;
	right: -4px;
	background: #d9534f;
	color: #fff;
	padding: 1px 6px;
	border-radius: 10px;
	font-size: 11px;
	font-weight: bold;
	min-width: 18px;
	text-align: center;
	line-height: 16px;
}
.groupslist-mobbody {
	flex: 1;
	min-width: 0;
}
.groupslist-mobtitle {
	font-size: 16px;
	line-height: 1.25;
	margin-bottom: 2px;
}
.groupslist-mobrole {
	font-size: 10px;
	margin-left: 4px;
	vertical-align: 2px;
}
.groupslist-moblock {
	margin-left: 6px;
	color: #999;
}
.groupslist-mobdesc {
	font-size: 12px;
	color: #666;
	line-height: 1.35;
	margin: 2px 0 4px;
	display: -webkit-box;
	-webkit-line-clamp: 2;
	-webkit-box-orient: vertical;
	overflow: hidden;
}
body.dark-mode .groupslist-mobdesc {
	color: var(--dark-mode-light-text-color);
}
.groupslist-mobmeta {
	font-size: 12px;
	color: #888;
}
.groupslist-mobmeta-sep {
	margin: 0 6px;
	color: #ccc;
}
.groupslist-mobpending-row {
	margin-top: 6px;
}
.groupslist-mobpending {
	display: inline-block;
	margin-right: 4px;
}

/* /post page: sender user-chip on the left, "# Add Tags" button on
   the right. Subject line below takes the full width. */
.grouppost-sender-row {
	display: flex;
	flex-wrap: nowrap;
	justify-content: space-between;
	align-items: center;
	gap: 6px;
	width: 100%;
}
.grouppost-sender-row .dropdown {
	flex: 1 1 auto;
	min-width: 0;
}
.grouppost-sender-row .dropdown .user-chip {
	max-width: 100%;
}
.grouppost-sender-row .grouppost-tags-btn {
	flex: 0 0 auto;
}

/* Rounded corners on the TinyMCE editor wrapper so it feels like a
   contained card instead of a bare rectangle, at the same radius as the
   form controls around it. overflow:hidden keeps the toolbar's own
   corners clipped to the outer radius. */
.tox.tox-tinymce {
	border-radius: 10px;
	overflow: hidden;
}

/* On xs, tighten the gap between the Subject row and the editor. */
@media (max-width: 767px) {
	#postform .form-group + .tox.tox-tinymce {
		margin-top: 0;
	}
	#postform .form-group {
		margin-bottom: 8px;
	}
}

/* Shared user-identity chip. Used as the "From" selector on
   /post and /reply, the sender dropdown on /pendingmsg, and
   similar user-identity dropdowns elsewhere. Reads as a tappable
   control rather than an underlined link. */
.user-chip {
	display: inline-flex;
	align-items: center;
	padding: 4px 12px 4px 4px;
	border: 1px solid #ccc;
	border-radius: 20px;
	background: #fff;
	color: #333;
	text-decoration: none;
	max-width: 100%;
}
.user-chip:hover,
.user-chip:focus,
.user-chip:active {
	background: #f2f5f9;
	color: #333;
	text-decoration: none;
	border-color: #b8bdc4;
}
body.dark-mode .user-chip {
	background: var(--dark-mode-primary-color);
	color: var(--dark-mode-text-color);
	border-color: var(--dark-mode-divider);
}
body.dark-mode .user-chip:hover,
body.dark-mode .user-chip:focus {
	background: var(--dark-mode-highlight-color);
	color: var(--dark-mode-text-color);
}
.user-chip-inner {
	display: inline-flex;
	align-items: center;
	gap: 8px;
	min-width: 0;
}
.user-chip-avatar {
	width: 32px;
	height: 32px;
	border-radius: 50%;
	flex: 0 0 32px;
}
.user-chip-avatar-icon {
	font-size: 28px;
	color: #b8bdc4;
	line-height: 1;
}
.user-chip-name {
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	max-width: 220px;
}
/* Non-interactive version: same avatar + name typography, but no
   border/background/hover. Used where a user is being displayed but
   has no associated dropdown. */
.user-chip-static {
	display: inline-flex;
	align-items: center;
	gap: 8px;
	min-width: 0;
}

/* /messages sticky-wiki alert: on xs, the multi-line wiki preview is
   collapsed behind a "📌 Pinned" chip that expands on tap. Desktop
   unchanged. */
.stickywiki-toggle {
	background: none;
	border: none;
	padding: 0;
	color: #337ab7;
	font-weight: 500;
	cursor: pointer;
}
.stickywiki-toggle i {
	margin-right: 4px;
}
.stickywiki-toggle-caret {
	transition: transform 0.15s ease;
}
.stickywiki-alert.open .stickywiki-toggle-caret {
	transform: rotate(180deg);
}
body.dark-mode .stickywiki-toggle {
	color: #8cb4df;
}
@media (max-width: 767px) {
	.stickywiki-alert {
		padding: 10px 28px 10px 14px;
	}
	.stickywiki-alert #stickywiki,
	.stickywiki-alert #readmorelink {
		display: none;
	}
	.stickywiki-alert.open #stickywiki,
	.stickywiki-alert.open #readmorelink {
		display: block;
		margin-top: 8px;
	}
}

/* /messages expanded view: hide subject-row on xs when the subject
   matches the previous message (thread continuation). */
.expanded-subject-dup {
	display: none;
}
@media (min-width: 768px) {
	.expanded-subject-dup {
		display: block;
	}
}

/* Footer strip at the bottom of an expanded-message card. Stretches
   to the card edges via negative margin; adds rounded bottom corners. */
.expanded-message-footer {
	margin-left: -10px;
	margin-right: -10px;
	margin-bottom: -10px;
	padding: 4px 10px 2px;
	border-bottom-left-radius: 4px;
	border-bottom-right-radius: 4px;
}

/* Reply / Like / More buttons under each message. Desktop shows icon
   + label; xs hides the label to keep the row compact. min-height of
   44px keeps the tap target comfortable on phones. All three buttons
   share the same inline-flex layout so they baseline-align. */
.msg-action {
	display: inline-flex;
	align-items: center;
	gap: 6px;
	min-height: 44px;
	padding: 0 4px;
	line-height: 1;
}
.msg-action-count {
	font-size: 12px;
	opacity: 0.75;
}
/* Align the More dropdown with the other action buttons, but only on
   the variant that's actually visible at each breakpoint — overriding
   `display` on the hidden variant would break the wide/narrow swap. */
@media (min-width: 768px) {
	.msg-more-drop.dropdown-wide {
		display: inline-flex;
		align-items: center;
		gap: 6px;
		min-height: 44px;
		padding: 0 4px;
		line-height: 1;
	}
}
@media (max-width: 767px) {
	.msg-action-label {
		display: none;
	}
	.msg-action i {
		font-size: 18px;
	}
	.msg-more-drop.dropdown-narrow {
		display: inline-flex;
		align-items: center;
		min-height: 44px;
		padding: 0 4px;
		line-height: 1;
		/* font-size: 0 hides the button's text label on xs while
		   the icon, explicitly sized below, stays visible. The
		   dropdown template renders the label inline and we can't
		   easily wrap it in its own span to hidden-xs it. */
		font-size: 0;
	}
	.msg-more-drop.dropdown-narrow i {
		font-size: 18px;
	}
}

/* /message single-message page: on mobile, indent the subject header
   so it aligns with the user chip and body inside the card below,
   instead of hugging the viewport edge. */
@media (max-width: 767px) {
	.groupmessage-subject {
		padding-left: 11px;
	}
}


/* /messages expanded view: layout for subject row. Date/link float
   right on the subject row; the sender user-chip sits on its own
   row below, left-aligned. */
.expanded-subject-row {
	display: flex;
	align-items: baseline;
	gap: 8px;
}
.expanded-subject-row .subject {
	flex: 1 1 auto;
	min-width: 0;
	order: 1;
}
.expanded-subject-meta {
	flex: 0 0 auto;
	text-align: right;
	white-space: nowrap;
	order: 2;
}
.expanded-sender-row {
	margin-top: 6px;
}
/* On pages that omit the in-card subject (/topic, /message), the
   per-message meta (date + permalink) floats right in the sender row
   so the user-chip keeps the left edge. */
.expanded-sender-col {
	display: flex;
	align-items: baseline;
	gap: 8px;
}
.expanded-sender-col .dropdown,
.expanded-sender-col .user-chip-static {
	flex: 1 1 auto;
	min-width: 0;
	order: 1;
}
.expanded-sender-meta {
	flex: 0 0 auto;
	text-align: right;
	white-space: nowrap;
	order: 2;
}

/* Bold the subject on mobile so it's easy to spot vs the message body. */
@media (max-width: 767px) {
	.subject,
	body.dark-mode .subject {
		font-weight: 600;
	}
}

/* Message-subject hashtag pills: let them wrap under the subject on
   xs instead of overflowing horizontally. */
@media (max-width: 767px) {
	.subject {
		display: inline;
	}
	.subject .hashtag-position,
	.subject .hashtag-btn {
		display: inline-block;
		margin-top: 4px;
	}
}

/* /post page: moderator posting options. Always visible on desktop;
   on xs, collapsed behind a "Posting options" toggle so the page
   isn't cluttered for the common composer. */
.grouppost-options-toggle {
	display: none;
	background: none;
	border: none;
	padding: 8px 0;
	color: #337ab7;
	font-weight: 500;
	cursor: pointer;
}
.grouppost-options-toggle i {
	margin-right: 4px;
}
.grouppost-options-caret {
	transition: transform 0.15s ease;
}
.grouppost-options.open .grouppost-options-caret {
	transform: rotate(180deg);
}
body.dark-mode .grouppost-options-toggle {
	color: #8cb4df;
}
@media (max-width: 767px) {
	.grouppost-options-toggle {
		display: inline-flex;
		align-items: center;
	}
	.grouppost-options:not(.open) .grouppost-options-body {
		display: none;
	}
}

/* database table */
.dbtable {
	border-top: none;
	border-bottom: none;
	background-color: #FFF;
}

.event-dot {
	display: inline-block;
	width: 10px;
	height: 10px;
	border-radius: 5px;
}

.album-owner a {
	color: white;
}

/* mobile hamburger drawer */
.drawer {
	display: none;
}

.drawer-header {
	padding: 1.5rem;
	display: flex;
	justify-content: space-between;
	align-items: center;
	border-bottom: 1px solid #ddd;
}

.drawer-close {
	margin: 0;
	padding: 0;
	border: none;
	background-color: transparent;
	cursor: pointer;
	background-image: url("data:image/svg+xml,%0A%3Csvg width='15px' height='16px' viewBox='0 0 15 16' version='1.1' xmlns='http://www.w3.org/2000/svg' xmlns:xlink='http://www.w3.org/1999/xlink'%3E%3Cg id='Page-1' stroke='none' stroke-width='1' fill='none' fill-rule='evenodd'%3E%3Cg id='2.-Menu' transform='translate(-15.000000, -13.000000)' stroke='%23000000'%3E%3Cg id='Group' transform='translate(15.000000, 13.521000)'%3E%3Cpath d='M0,0.479000129 L15,14.2971819' id='Path-3'%3E%3C/path%3E%3Cpath d='M0,14.7761821 L15,-1.24344979e-14' id='Path-3'%3E%3C/path%3E%3C/g%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
	width: 15px;
	height: 15px;
}

.drawer-wrapper {
	position: fixed;
	top: 0;
	right: 0;
	bottom: 0;
	height: 100%;
	width: 100%;
	max-width: 500px;
	z-index: 9999;
	overflow: auto;
	transition: transform 0.2s;
	will-change: transform;
	background-color: #fff;
	display: flex;
	flex-direction: column;
	-webkit-transform: translateX(103%);
	transform: translateX(103%);
	/* extra 3% because of box-shadow */
	-webkit-overflow-scrolling: touch;
	/* enables momentum scrolling in iOS overflow elements */
	box-shadow: 0 2px 6px #707070;
}

.drawer-wrapper-top {
	padding-top: max(0px, env(safe-area-inset-top));
}

.drawer-content {
	position: relative;
	overflow-x: hidden;
	overflow-y: auto;
	height: 100%;
	flex-grow: 1;
	padding: 1.5rem;
}

.drawer.is-active {
	display: inline;
}

.drawer.is-visible .drawer-wrapper {
	-webkit-transform: translateX(0);
	transform: translateX(0);
}

.drawer.is-visible .drawer-overlay {
	opacity: 0.5;
}

.drawer-overlay {
	position: fixed;
	top: 0;
	right: 0;
	bottom: 0;
	left: 0;
	width: 100%;
	z-index: 200;
	opacity: 0;
	transition: opacity 0.2s;
	will-change: opacity;
	background-color: #000;
	-webkit-user-select: none;
	-moz-user-select: none;
	-ms-user-select: none;
	user-select: none;
}

.drawer-left .drawer-wrapper {
	left: 0;
	right: auto;
	-webkit-transform: translate3d(-100%, 0, 0);
	transform: translate3d(-100%, 0, 0);
}

.drawer-bottom .drawer-wrapper {
	top: auto;
	right: 0;
	bottom: 0;
	left: 0;
	height: auto;
	width: 100%;
	max-height: 500px;
	max-width: none;
	-webkit-transform: translateY(103%);
	transform: translateY(103%);
	/* extra 3% because of box-shadow */
}

body.app .navbar-fixed-top {
	padding-top: max(0px, env(safe-area-inset-top));
	/*padding-bottom: max(20px, env(safe-area-inset-bottom));*/
}

/* attachment display */
.attachment-box {
	border: 1px solid #f5f5f5;
	margin: 10px;
	text-align: center;
	height: 100px;
	width: 150px;
	position: relative;
	transition: background-color 0.2s ease;
}

.attachment-box:hover {
	background-color: #f5f5f5;
}

.attachment-icon,
.attachment-image {
	transition: opacity 0.2s ease;
}

.attachment-icon {
	font-size: 40px;
	margin-top: 15px;
}

.attachment-image {
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 100%;
	object-fit: cover;
}

/* On phones, when an attachment row contains any image, switch to a
   responsive 2-column flex grid with taller cells so photos are
   actually viewable instead of cramped 150x100 thumbnails. Two
   images split 50/50; three or more wrap into rows of two (a lone
   third item stays at 50% width instead of stretching). */
@media (max-width: 767px) {
	.attachment-row:has(.attachment-image) {
		display: flex;
		flex-wrap: wrap;
		gap: 4px;
		margin-left: 0;
		margin-right: 0;
	}
	/* Bootstrap 3's .row clearfix pseudo-elements become zero-width
	   flex items that offset the first child by one gap. Suppress
	   them so the grid aligns at the row's left edge. */
	.attachment-row:has(.attachment-image)::before,
	.attachment-row:has(.attachment-image)::after {
		display: none;
	}
	.attachment-row:has(.attachment-image) > a {
		flex: 1 1 calc(50% - 4px);
		min-width: 0;
		padding: 0;
		display: block;
	}
	.attachment-row:has(.attachment-image) > a > .attachment-box {
		width: 100%;
		height: 180px;
		margin: 0;
	}
}

.attachment-box:hover .attachment-icon,
.attachment-box:hover .attachment-image {
	opacity: 0;
}

.attachment-name,
.attachment-name-hover {
	background-color: #f5f5f5;
	padding: 5px;
	position: absolute;
	bottom: 0;
	left: 0;
	right: 0;
	font-size: 12px;
	transition: opacity 0.2s ease;
}

.attachment-name {
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.attachment-name-hover {
	opacity: 0;
}

.attachment-box:hover .attachment-name {
	opacity: 0;
}

.attachment-box:hover .attachment-name-hover {
	opacity: 1;
}

.delete-checkbox {
	position: absolute;
	top: 5px;
	right: 5px;
}

/* files move tree */
.tree,
.tree ul {
	margin: 0;
	padding: 0;
	list-style: none
}

.tree ul {
	margin-left: 1em;
	position: relative
}

.tree ul ul {
	margin-left: .5em
}

.tree ul:before {
	content: "";
	display: block;
	width: 0;
	position: absolute;
	top: 0;
	bottom: 0;
	left: 0;
	border-left: 1px solid
}

.tree li {
	margin: 0;
	padding: 0 1em;
	line-height: 2em;
	font-weight: 700;
	position: relative
}

.tree ul li:before {
	content: "";
	display: block;
	width: 10px;
	height: 0;
	border-top: 1px solid;
	margin-top: -1px;
	position: absolute;
	top: 1em;
	left: 0
}

.tree ul li:last-child:before {
	background: #fff;
	height: auto;
	top: 1em;
	bottom: 0
}

.treeindicator {
	margin-right: 5px;
}

.tree li a {
	text-decoration: none;
}

.tree li button,
.tree li button:active,
.tree li button:focus {
	text-decoration: none;
	border: none;
	background: transparent;
	margin: 0px 0px 0px 0px;
	padding: 0px 0px 0px 0px;
	outline: 0;
}

.maincontent-column {
	height:100%;
}
.maincontent-chat-column {
	position: absolute;
	top: calc(55px + env(safe-area-inset-top));
	bottom: env(safe-area-inset-bottom);
	right: 0;
	left: 235px;
	width: calc(100vw - 235px);
	padding-right:0px;
	margin-bottom: 0px !important;
}

/* chat */
#chat-container {
	display: flex;
	flex-direction: column;
	width: 100%;
	height: calc(100% - 0px);
	margin: 0 auto;
	box-sizing: border-box;
	font-size: 17px;
}

@media (max-width: 991.98px) {
	/* adjust margins for narrow screens */
	.container,
	.container-fluid {
		padding-left: 5px;
		padding-right: 5px;
	}

	.row {
		margin-left: -5px;
		margin-right: -5px;
	}

	/* Bring every Bootstrap column to the same 5px gutter as col-xs-12
	   so side-by-side halves (e.g., Start Date + Start Time) line up
	   with the full-width fields above and below them. Without this,
	   col-xs-6 inherits Bootstrap's default 15px padding and the half-
	   width inputs get inset 10px further than their siblings. */
	.col-xs-1, .col-xs-2, .col-xs-3, .col-xs-4, .col-xs-5, .col-xs-6,
	.col-xs-7, .col-xs-8, .col-xs-9, .col-xs-10, .col-xs-11, .col-xs-12,
	.narrow-padding {
		padding-left: 5px;
		padding-right: 5px;
	}

	#maincontent {
		position: absolute;
		top: calc(55px + env(safe-area-inset-top));
		bottom: 80px;
		right: 0;
		left: 0;
		/* COMMENTED OUT for now because it causes HTMX to not handle infinite scrolling correctly. It causes a jump back to the top of the page. */
		/*overflow-y: auto !important;*/
	}

	/* added this in when we commented out overflow-y above. */
	#maincontent-column {
		padding-bottom: 100px;
	}

	.maincontent-chat-column {
		top: 0px !important;
		left: 0px !important;
		width: 100% !important;
		padding-bottom: 0px !important;
		padding-left: 0px;
	}

	#chat-container {
		height: 100%;
	}
}

#chat-messages {
	flex: 1;
	overflow-y: auto;
	padding: 10px;
	display: flex;
	flex-direction: column;
}

#chat-messages-wrapper {
	display: flex;
	flex-direction: column;
	align-items: flex-end;
}

#chat-preview {
	padding: 10px;
	align-items: center;
}

/* chat video thumbnails are wrapped in an <a> that opens the video modal;
   the default underline on the anchor shows up as a stray underscore next
   to the image since the anchor only contains whitespace + an <img>. */
a.video-link, a.video-link:hover, a.video-link:focus {
	text-decoration: none;
}

/* File attachment card in the composer preview (before sending) and in
   delivered messages (after). Both use the same inner layout: icon on the
   left, filename + size stacked in the middle, download chevron on the
   right for delivered ones. */
.thumbnail.chat-preview-file {
	display: flex;
	align-items: center;
	gap: 10px;
	padding: 10px 12px;
	min-width: 220px;
	max-width: 320px;
	background: #f5f5f5;
	border-radius: 10px;
}
.chat-preview-file-icon {
	font-size: 26px;
	color: #337ab7;
	flex-shrink: 0;
}
.chat-preview-file-meta {
	flex: 1;
	min-width: 0;
}
.chat-preview-file-name {
	font-size: 14px;
	font-weight: 500;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.chat-preview-file-size {
	font-size: 12px;
	color: #888;
}

/* In-message version: link, so it needs to override default anchor styling
   and provide a pressed/hover state. */
a.chat-file-card {
	display: flex;
	align-items: center;
	gap: 10px;
	padding: 10px 12px;
	min-width: 0;
	max-width: 100%;
	background: rgba(0, 0, 0, 0.06);
	border-radius: 10px;
	text-decoration: none !important;
	color: inherit;
}

/* Wrapper span around chat media is inline by default, which lets a
   flex child (e.g. .chat-file-card with a long filename) overflow its
   parent bubble. Make it a block with max-width:100% so the card's
   own max-width:100% actually constrains to the bubble. */
[id^="msgpayload-"] {
	display: block;
	max-width: 100%;
	min-width: 0;
}
a.chat-file-card:hover,
a.chat-file-card:focus {
	background: rgba(0, 0, 0, 0.10);
	text-decoration: none !important;
}
.chat-message.sent a.chat-file-card {
	background: rgba(255, 255, 255, 0.15);
	color: #fff;
}
.chat-message.sent a.chat-file-card:hover,
.chat-message.sent a.chat-file-card:focus {
	background: rgba(255, 255, 255, 0.22);
}
.chat-file-card-icon {
	font-size: 26px;
	color: inherit;
	flex-shrink: 0;
}
.chat-file-card-meta {
	flex: 1;
	min-width: 0;
}
.chat-file-card-name {
	font-size: 14px;
	font-weight: 500;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.chat-file-card-size {
	font-size: 12px;
	opacity: 0.7;
}
.chat-file-card-action {
	font-size: 16px;
	opacity: 0.6;
	flex-shrink: 0;
}
body.dark-mode .thumbnail.chat-preview-file {
	background: #2b2b2b;
	color: #e9ecef;
}
body.dark-mode a.chat-file-card {
	background: rgba(255, 255, 255, 0.08);
}
body.dark-mode a.chat-file-card:hover,
body.dark-mode a.chat-file-card:focus {
	background: rgba(255, 255, 255, 0.14);
}

/* video in chat reply preview: thumbnail with a play-icon overlay so the user
   can tell at a glance they've attached a video instead of an image. */
.thumbnail.chat-preview-video {
	position: relative;
}
.chat-preview-video-play {
	position: absolute;
	top: 50%;
	left: 50%;
	transform: translate(-50%, -50%);
	font-size: 42px;
	color: rgba(255, 255, 255, 0.9);
	text-shadow: 0 1px 6px rgba(0, 0, 0, 0.6);
	pointer-events: none;
}

.chat-form {
	display: flex;
	padding: 10px;
	align-items: center;
	background-color: #f8f8f8;
}

.chat-button-color {
	background-color: #f8f8f8
}

.chat-message-content-wrapper {
	display: flex;
	flex-direction: row;
	max-width: 100%;
	min-width: 0;
}

/* Chat video viewer. Edge-to-edge black on mobile (iOS-photos feel),
   aspect-fit and centered on desktop. Replaces the Bootstrap-default
   modal chrome so a portrait video inside a square-ish dialog no
   longer leaves empty white margins or gets clipped off-screen. */
.modal.video-modal {
	padding: 0 !important;
}
.modal.video-modal.in,
.modal.video-modal.show {
	display: flex !important;
}
.video-modal-dialog {
	margin: 0 auto;
	width: 100%;
	max-width: 100vw;
	/* dvh tracks the iOS URL-bar collapse; plain vh leaves the viewer
	   taller than visible and clips the bottom of the video. */
	height: 100dvh;
	padding: 0;
	pointer-events: auto;
}
.video-modal-content {
	background: #000;
	border: none;
	border-radius: 0;
	height: 100%;
	display: flex;
	flex-direction: column;
	box-shadow: none;
	position: relative;
}
.video-modal-body {
	flex: 1 1 auto;
	display: flex;
	align-items: center;
	justify-content: center;
	overflow: hidden;
	min-height: 0;
	background: #000;
}
.video-modal-player {
	width: 100%;
	height: 100%;
	max-height: 100%;
	max-width: 100%;
	object-fit: contain;
	background: #000;
	outline: none;
}
/* Floating circular close button in the top-right corner. 44px tap
   target meets the iOS HIG minimum; safe-area-inset keeps it below
   notches and the iOS status bar. */
.video-modal-close {
	position: absolute;
	top: calc(12px + env(safe-area-inset-top));
	right: calc(12px + env(safe-area-inset-right));
	width: 44px;
	height: 44px;
	border: none;
	border-radius: 50%;
	background: rgba(0, 0, 0, 0.55);
	color: #fff;
	font-size: 18px;
	line-height: 1;
	cursor: pointer;
	z-index: 10;
	display: flex;
	align-items: center;
	justify-content: center;
	opacity: 0.9;
	transition: opacity 0.15s, background-color 0.15s;
	-webkit-touch-callout: none;
	-webkit-user-select: none;
	user-select: none;
}
.video-modal-close:hover,
.video-modal-close:focus {
	opacity: 1;
	background: rgba(0, 0, 0, 0.75);
	color: #fff;
	outline: none;
}
/* Bottom metadata strip: sender · time  [Download] */
.video-modal-meta {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 12px;
	padding: 10px 16px calc(10px + env(safe-area-inset-bottom));
	background: rgba(0, 0, 0, 0.72);
	color: rgba(255, 255, 255, 0.92);
	font-size: 13px;
	flex-shrink: 0;
}
.video-modal-meta-info {
	min-width: 0;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.video-modal-meta-sender {
	font-weight: 600;
}
.video-modal-meta-sep {
	opacity: 0.6;
	margin: 0 4px;
}
.video-modal-meta-date {
	opacity: 0.85;
}
.video-modal-download {
	border: none;
	background: rgba(255, 255, 255, 0.14);
	color: #fff;
	border-radius: 6px;
	padding: 8px 12px;
	font-size: 13px;
	display: inline-flex;
	align-items: center;
	gap: 6px;
	flex-shrink: 0;
	cursor: pointer;
	transition: background-color 0.15s;
	min-height: 36px;
}
.video-modal-download:hover,
.video-modal-download:focus {
	background: rgba(255, 255, 255, 0.24);
	color: #fff;
	outline: none;
}

/* Desktop: centred viewer with rounded corners, not fullscreen.
   Dimensions are set inline by JS on `loadedmetadata` to match the
   video's natural aspect ratio — otherwise a portrait clip in a
   fixed-size box leaves black bars on either side. Caps below apply
   before metadata loads or as an upper bound if JS can't size. */
@media (min-width: 768px) {
	.modal.video-modal.in,
	.modal.video-modal.show {
		align-items: center;
		justify-content: center;
	}
	.video-modal-dialog {
		width: auto;
		max-width: 95vw;
		height: auto;
		max-height: 95dvh;
		margin: 0 auto;
	}
	.video-modal-content {
		width: auto;
		height: auto;
		max-width: min(960px, 95vw);
		max-height: min(720px, 95dvh);
		border-radius: 12px;
		overflow: hidden;
	}
	.video-modal-body {
		min-height: 0;
	}
}

/* Audio voice-message bubble. A subtle translucent container holds
   the play button and a waveform. Colours adapt to the surrounding
   chat-message context (received / sent / dark mode) so the controls
   always contrast with the bubble behind them. Waveform bars use
   currentColor so a single `color` override per context retints them.
   Lives in the main stylesheet (not an ExtraHeader <style>) so the
   rules are still present after HTMX partial swaps into /chat/. */
.audio-waveform-container {
	background-color: rgba(0, 0, 0, 0.05);
	border-radius: 18px;
	padding: 6px 12px 6px 6px;
	color: #6b6b6b;
}
.dark-mode .audio-waveform-container {
	background-color: rgba(255, 255, 255, 0.08);
	color: #bfbfbf;
}
/* Sent (blue) bubble: the default blue button would vanish into the
   bubble. Flip the palette — white pill button with a blue play icon,
   translucent-white waveform bars. */
.chat-message.sent .audio-waveform-container {
	background-color: rgba(255, 255, 255, 0.15);
	color: rgba(255, 255, 255, 0.85);
}
.audio-waveform {
	border-radius: 4px;
	height: 36px;
}
/* Clip duration shown to the right of the waveform. Inherits `color`
   from the container (retinted per bubble context), so contrast stays
   correct on sent/received/dark bubbles. */
.audio-duration {
	font-size: 12px;
	font-variant-numeric: tabular-nums;
	opacity: 0.8;
	flex-shrink: 0;
}
.audio-play-button {
	width: 36px;
	height: 36px;
	border-radius: 50%;
	border: none;
	background-color: #337ab7;
	color: #fff;
	cursor: pointer;
	display: flex;
	align-items: center;
	justify-content: center;
	font-size: 13px;
	flex-shrink: 0;
	transition: background-color 0.2s;
}
/* The fa-play glyph has whitespace to its right inside the bounding
   box, so flex-centring leaves the triangle visually shifted left.
   Nudge it right for optical centring. Undone when the icon class
   switches to fa-pause (symmetric glyph). */
.audio-play-button .fa-play {
	transform: translateX(1px);
}
.audio-play-button:hover {
	background-color: #2a6496;
}
.audio-play-button:active {
	background-color: #1f4e78;
}
.dark-mode .audio-play-button {
	background-color: #4a90e2;
}
.dark-mode .audio-play-button:hover {
	background-color: #3a7bc8;
}
.chat-message.sent .audio-play-button {
	background-color: #fff;
	color: #337ab7;
}
.chat-message.sent .audio-play-button:hover {
	background-color: #eef3f8;
}
.chat-message.sent .audio-play-button:active {
	background-color: #dde7f2;
}

.chat-message {
	position: relative;
	margin-bottom: 10px;
	display: flex;
	flex-direction: row;
	max-width: 80%;
}

.chat-message-content {
	display: flex;
	flex-direction: column;
	padding: 5px;
	border-radius: 10px;
	word-break: break-word;
	max-width: 100%;
	min-width: 0;
}


/* Ask answer-bubble actions: icon-only links beside the bubble, labels
   provided by tooltips. nowrap keeps them from stacking in the flex row. */
.chat-message-actions {
	align-self: flex-start;
	white-space: nowrap;
	padding: 5px 0 0 8px;
}

.chat-message-actions a {
	color: #999;
	margin-right: 8px;
}

.chat-message-actions a:hover {
	color: #337ab7;
}

/* Bubble content is markdown-rendered: without this, the final paragraph's
   bottom margin adds to the bubble padding and makes bubbles bottom-heavy. */
.chat-message-content p:last-child {
	margin-bottom: 0;
}

.chat-message.received .chat-message-content {
	background-color: rgb(233, 233, 233);
}

.chat-message.received .chat-message-content a {
	text-decoration: underline;
}

.chat-message.sent .chat-message-content {
	background-color: #337ab7;
	color: rgb(224, 231, 243);
}

.chat-message.sent .chat-message-content a {
	color: rgb(224, 231, 243);
	text-decoration: underline;
}

.chat-message.received {
	align-self: flex-start;
}

.chat-message.date .chat-message-content {
