/* Typing indicator: strip above the composer that shows "X is typing…"
   with three pulsing dots. Rendered once per user; automatically removes
   itself after the typing event stops arriving. */
.chat-typing-indicator {
	padding: 4px 12px;
	font-size: 12px;
	color: #888;
	background: transparent;
}
.chat-typing-row {
	display: flex;
	align-items: center;
	gap: 6px;
	padding: 2px 0;
}
.chat-typing-name {
	font-style: italic;
}
.chat-typing-dots {
	display: inline-flex;
	gap: 3px;
	align-items: center;
}
.chat-typing-dots span {
	width: 5px;
	height: 5px;
	border-radius: 50%;
	background: #888;
	opacity: 0.35;
	animation: chat-typing-bounce 1.2s infinite ease-in-out both;
}
.chat-typing-dots span:nth-child(2) { animation-delay: 0.15s; }
.chat-typing-dots span:nth-child(3) { animation-delay: 0.30s; }
@keyframes chat-typing-bounce {
	0%, 80%, 100% { transform: translateY(0); opacity: 0.35; }
	40%           { transform: translateY(-3px); opacity: 1; }
}

/* Emoji picker: anchored above the composer. Kept compact on mobile so it
   doesn't swallow the chat history, and wide-open on desktop. */
#chat-emoji-picker {
	position: absolute;
	bottom: 60px;
	left: 8px;
	right: 8px;
	max-height: 260px;
	overflow-y: auto;
	background: #fff;
	border: 1px solid #ddd;
	border-radius: 8px;
	box-shadow: 0 -2px 8px rgba(0, 0, 0, 0.08);
	padding: 8px;
	z-index: 20;
}
@media (min-width: 768px) {
	#chat-emoji-picker {
		left: auto;
		right: 10px;
		width: 340px;
	}
}
.emoji-picker-label {
	font-size: 11px;
	text-transform: uppercase;
	color: #888;
	letter-spacing: 0.04em;
	margin: 6px 2px 4px;
}
.emoji-picker-grid {
	display: grid;
	grid-template-columns: repeat(auto-fill, minmax(36px, 1fr));
	gap: 2px;
}
.emoji-picker-btn {
	background: transparent;
	border: 0;
	padding: 4px;
	font-size: 22px;
	line-height: 1;
	border-radius: 4px;
	cursor: pointer;
}
.emoji-picker-btn:hover,
.emoji-picker-btn:focus {
	background: #eef3fa;
	outline: none;
}
body.dark-mode #chat-emoji-picker {
	background: #2b2b2b;
	border-color: #444;
}
body.dark-mode .emoji-picker-btn:hover,
body.dark-mode .emoji-picker-btn:focus {
	background: #3b4657;
}

/* Swipe-to-reply indicator: a small reply arrow revealed in the message
   gutter as the bubble slides left during a horizontal swipe. Goes solid
   blue once the user has swiped far enough to trigger the reply. */
.chat-swipe-reply-hint {
	position: absolute;
	right: 8px;
	top: 50%;
	transform: translateY(-50%);
	font-size: 18px;
	color: #999;
	opacity: 0;
	pointer-events: none;
	transition: color 100ms ease;
}
.chat-swipe-reply-hint.armed {
	color: #337ab7;
}

/* Grouped: this message follows another message from the same user within
   the group-gap window. Tighten spacing and hide the repeated header
   (avatar/username) and trailing timestamp so a run of messages reads as a
   single cluster instead of a stack of isolated bubbles. */
.chat-message.grouped {
	margin-bottom: 2px;
}
/* A grouped message that also has tapbacks still needs the full 30px gutter
   so the tapback chip doesn't overlap the next bubble in the group. */
.chat-message.grouped.emojimargin {
	margin-bottom: 30px;
}
/* File-card bubbles have a solid-color card that starts right at the bubble's
   top edge, so any incoming tapback from the message above visually sits
   on top of the card. Give them a little top margin to push them clear.
   :has() is widely supported in current browsers; it no-ops where it isn't. */
.chat-message:has(a.chat-file-card) {
	margin-top: 6px;
}
.chat-message.emojimargin + .chat-message:has(a.chat-file-card) {
	margin-top: 14px;
}
.chat-message.grouped .chat-profile-picture-wrapper {
	visibility: hidden;
}
.chat-message.received.grouped .chat-message-content > span[id^="msguser-"],
.chat-message.sent.grouped .chat-message-content > span[id^="msguser-"] {
	display: none;
}
.chat-message.grouped .chat-timestamp-sent,
.chat-message.grouped .chat-timestamp-received {
	display: none;
}

