/* image viewer */
.viewer-overlay {
	display: none;
	position: fixed;
	top: 0;
	left: 0;
	width: 100%;
	height: 100%;
	background-color: #000;
	z-index: 9999;
}

.viewer-overlay.visible {
	display: flex;
	justify-content: center;
	align-items: center;
}

.viewer-overlay-controls {
	position: absolute;
	top: 25px;
	right: 25px;
	padding-top: env(safe-area-inset-top);
	z-index: 1000;
}

.viewer-image-container {
	display: flex;
	justify-content: center;
	align-items: center;
	position: relative;
	height: 80vh;
	width: 80vw;
	/* Reduced width */
	padding: 0 40px;
	/* Padding added */
	padding-top: env(safe-area-inset-top);
	/* Own horizontal gestures so the swipe handler can drive image paging;
	   vertical pan and pinch-zoom still go through to the browser. */
	touch-action: pan-y pinch-zoom;
}
.viewer-image-container img#currentImage {
	-webkit-user-drag: none;
	user-select: none;
	will-change: transform;
}

.viewer-arrow {
	color: #FFF;
	position: absolute;
	top: 50%;
	z-index: 1001;
