	stroke: var(--dark-mode-divider) !important;
}

.analytics-page body.dark-mode svg .domain {
	stroke: var(--dark-mode-divider) !important;
}

body.dark-mode code {
	background-color: var(--dark-mode-primary-color) !important;
}

/* ============================================
   Image Lightbox Styles
   ============================================ */

/* Inline image hover effect with download icon */
.lightbox-image {
	position: relative;
	cursor: pointer !important;
	transition: opacity 0.2s ease;
}

.lightbox-image:hover {
	opacity: 0.9;
}

/* Wrapper for inline images to add download icon on hover */
.lightbox-image::after {
	content: "\f019"; /* Font Awesome download icon */
	font-family: "Font Awesome 5 Free";
	font-weight: 900;
	position: absolute;
	bottom: 8px;
	right: 8px;
	background-color: rgba(0, 0, 0, 0.6);
	color: white;
	padding: 6px 8px;
	border-radius: 3px;
	font-size: 12px;
	opacity: 0;
	transition: opacity 0.2s ease;
	pointer-events: none;
}

.lightbox-image:hover::after {
	opacity: 1;
}

/* Lightbox navigation buttons */
.lightbox-nav {
	position: absolute;
	top: 50%;
	transform: translateY(-50%);
	z-index: 10;
	background-color: rgba(0, 0, 0, 0.5) !important;
	border: none !important;
	color: white !important;
	padding: 15px 12px;
	font-size: 20px;
	transition: background-color 0.2s ease;
}

.lightbox-nav:hover {
	background-color: rgba(0, 0, 0, 0.7) !important;
	color: white !important;
}

.lightbox-nav:focus {
	outline: none;
	box-shadow: 0 0 0 3px rgba(66, 139, 202, 0.5);
}

.lightbox-nav-prev {
	left: 10px;
}

.lightbox-nav-next {
	right: 10px;
}

/* Lightbox modal customizations */
#imageLightbox .modal-dialog {
	max-width: 90vw;
	width: auto;
	margin: 30px auto;
}

#imageLightbox .modal-body {
	padding: 20px;
	min-height: 300px;
	display: flex;
	align-items: center;
	justify-content: center;
}

#imageLightbox #lightboxImage {
	max-width: 100%;
	max-height: 70vh;
	width: auto;
	height: auto;
	object-fit: contain;
}

#imageLightbox #lightboxCounter {
	color: #666;
	font-size: 14px;
}

/* Dark mode adjustments for lightbox */
body.dark-mode #imageLightbox .modal-content {
	background-color: var(--dark-mode-primary-color);
	color: var(--dark-mode-text-color);
}

body.dark-mode #imageLightbox .modal-header {
	border-bottom-color: var(--dark-mode-divider);
}

body.dark-mode #imageLightbox .modal-footer {
	border-top-color: var(--dark-mode-divider);
}

body.dark-mode #imageLightbox #lightboxCounter {
	color: var(--dark-mode-light-text-color);
}

body.dark-mode #imageLightbox #lightboxTextContent {
	background-color: var(--dark-mode-highlight-color) !important;
	color: var(--dark-mode-text-color);
}

/* Attachment lightbox styling */
.lightbox-attachment {
	cursor: pointer;
	text-decoration: none;
}

.lightbox-attachment:hover {
	text-decoration: none;
}

/* Responsive adjustments */
@media (max-width: 768px) {
	#imageLightbox .modal-dialog {
		max-width: 100%;
		margin: 10px;
	}

	#imageLightbox #lightboxImage {
		max-height: 60vh;
	}

	.lightbox-nav {
		padding: 10px 8px;
		font-size: 16px;
	}
}

/* =========================================================================
   Native-feel polish (applies at all widths). These rules sit at the end of
   the stylesheet so they override Bootstrap defaults by source order without
   needing !important.
   ========================================================================= */

/* 1. Brand-tinted native form controls. One-liner that colors checkboxes,
      radios, and range sliders with the brand blue — no JS, no custom
      components, no markup changes. */
input[type="checkbox"],
input[type="radio"],
input[type="range"] {
	accent-color: #337ab7;
}

/* 2. Selection highlight picks up the brand tint instead of the OS default.
      Subtle enough to stay legible over any background. */
::selection {
	background-color: rgba(51, 122, 183, 0.25);
	color: inherit;
}
::-moz-selection {
	background-color: rgba(51, 122, 183, 0.25);
	color: inherit;
}

/* 3. Softer form-input treatment. Gentle radius, thin border, no inner
      shadow. Keeping Bootstrap's default height/padding so inputs line up
      with adjacent input-group addons, buttons, and inline labels. Focus
      ring only for keyboard users via :focus-visible — touch and
      click-focus stay quiet. */
input[type="text"],
input[type="email"],
input[type="password"],
input[type="number"],
input[type="tel"],
input[type="url"],
input[type="search"],
input[type="date"],
input[type="time"],
input[type="datetime-local"],
select,
textarea,
.form-control {
	border-radius: 10px;
	border: 1px solid #d6d9de;
	box-shadow: none;
	transition: border-color 120ms ease, box-shadow 120ms ease;
}
/* Native date/time inputs on mobile add an inline glyph and extra user-
   agent padding, which makes them taller than sibling text inputs that use
   Bootstrap's .form-control. Force them to the same box model so a native
   <input type=date> lines up with a flatpickr-wrapped <input type=text>.
   iOS also defaults date/time inputs to centered text; align left to match
   the rest of the form. */
input[type="date"].form-control,
input[type="time"].form-control,
input[type="datetime-local"].form-control {
	height: 34px;
	padding: 6px 12px;
	line-height: 1.42857143;
	box-sizing: border-box;
	text-align: left;
	-webkit-appearance: none;
	appearance: none;
}
input[type="text"]:focus,
input[type="email"]:focus,
input[type="password"]:focus,
input[type="number"]:focus,
input[type="tel"]:focus,
input[type="url"]:focus,
input[type="search"]:focus,
input[type="date"]:focus,
input[type="time"]:focus,
input[type="datetime-local"]:focus,
select:focus,
textarea:focus,
.form-control:focus {
	outline: none;
	box-shadow: none;
	border-color: #337ab7;
}
/* Keyboard-only focus gets a visible accent ring. */
input[type="text"]:focus-visible,
input[type="email"]:focus-visible,
input[type="password"]:focus-visible,
input[type="number"]:focus-visible,
input[type="tel"]:focus-visible,
input[type="url"]:focus-visible,
input[type="search"]:focus-visible,
input[type="date"]:focus-visible,
input[type="time"]:focus-visible,
input[type="datetime-local"]:focus-visible,
select:focus-visible,
textarea:focus-visible,
.form-control:focus-visible {
	box-shadow: 0 0 0 3px rgba(51, 122, 183, 0.25);
	border-color: #337ab7;
}
body.dark-mode input[type="text"],
body.dark-mode input[type="email"],
body.dark-mode input[type="password"],
body.dark-mode input[type="number"],
body.dark-mode input[type="tel"],
body.dark-mode input[type="url"],
body.dark-mode input[type="search"],
body.dark-mode select,
body.dark-mode textarea,
body.dark-mode .form-control {
	border-color: var(--dark-mode-divider);
	box-shadow: none;
}

/* 4. Strip underlines from chrome links. Message/user content stays
      underlined via a higher-specificity selector in the ChatMessage /
      archive CSS; here we just quiet the navigation, pagination, and badge
      links that otherwise look very 2010-web. */
.pagination a,
.pagination a:hover,
.pagination a:focus,
.breadcrumb a,
.breadcrumb a:hover,
.breadcrumb a:focus,
.scroll-breadcrumb a,
.scroll-breadcrumb a:hover,
.scroll-breadcrumb a:focus,
.label a,
.label a:hover,
.badge a,
.badge a:hover,
.nav a,
.nav a:hover,
.list-group-item,
.list-group-item:hover,
.list-group-item:focus,
.dropdown-menu a,
.dropdown-menu a:hover,
.dropdown-menu a:focus,
.navbar a,
.navbar a:hover,
.navbar a:focus,
.thread-attribution a,
.thread-attribution a:hover,
.button-link,
.button-link:hover,
.button-link:focus {
	text-decoration: none;
}

/* 5. Soft-card treatment for Bootstrap panels and wells. Replaces the
      default 1px-border-on-white look with a rounded, borderless surface
      and a very subtle shadow so cards feel like lifted surfaces rather
      than framework chrome. */
.panel,
.panel-default,
.well,
.well-sm,
.well-lg {
	border: 0;
	border-radius: 12px;
	box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04), 0 1px 6px rgba(0, 0, 0, 0.04);
	overflow: hidden;
}
.well,
.well-sm,
.well-lg {
	background-color: var(--light-mode-primary-color);
}
body.dark-mode .panel,
body.dark-mode .panel-default,
body.dark-mode .well,
body.dark-mode .well-sm,
body.dark-mode .well-lg {
	box-shadow: 0 1px 2px rgba(0, 0, 0, 0.35), 0 1px 6px rgba(0, 0, 0, 0.35);
	background-color: var(--dark-mode-primary-color);
}

/* 6. Panel heading → uppercase section label instead of the chunky gray
      bar. Matches the 16px body-label weight so the heading feels like a
      peer of the content it groups, and uses flex so any right-side
      chevron (collapsable panels) stays vertically centered with the
      text. Horizontal padding matches the panel-body below so the label
      and the form fields line up on the same left edge. */
.panel-default > .panel-heading {
	background: transparent;
	border: 0 !important;
	padding: 16px 18px;
	font-size: 15px;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: 0.04em;
	color: #555;
	line-height: 1.4;
}
.panel-default > .panel-heading .panel-title,
.panel-default > .panel-heading h1,
.panel-default > .panel-heading h2,
.panel-default > .panel-heading h3,
.panel-default > .panel-heading h4 {
	font-size: inherit;
	font-weight: inherit;
	text-transform: inherit;
	letter-spacing: inherit;
	color: inherit;
	line-height: inherit;
	margin: 0;
	display: flex;
	align-items: center;
	justify-content: space-between;
}
.panel-default > .panel-heading .panel-title > a,
.panel-default > .panel-heading .panel-title > a:hover,
.panel-default > .panel-heading .panel-title > a:focus {
	color: inherit;
	text-decoration: none;
	display: flex;
	align-items: center;
	justify-content: space-between;
	width: 100%;
}
/* Collapsable chevron was using float:right which conflicts with the
   flex layout above. Let flex place it at the end instead. */
.panel-collapsable .panel-title > a:after,
.panel-collapsable .panel-title > a.collapsed:after {
	float: none;
	margin-left: auto;
}
/* Match the panel-body's horizontal padding so the heading text and the
   form content beneath it line up. Bootstrap collapsible panels wrap the
   body in .panel-collapse, so we use a descendant selector to catch both
   the flat and collapsible layouts. */
.panel-default .panel-body {
	padding: 8px 18px 16px;
}
@media (max-width: 767px) {
	/* Tighten the card's horizontal gutter on phones so forms have room
	   to breathe edge-to-edge. Heading padding-left is adjusted to match
	   so the uppercase label still lines up with the form content. */
	.panel-default .panel-body {
		padding-left: 12px;
		padding-right: 12px;
	}
	.panel-default > .panel-heading {
		padding-left: 12px;
		padding-right: 12px;
	}
	/* The event-name row uses a flex container with an inline 5px right
	   margin on #nameform to separate it from the "Add Tags" button. On
	   a phone that margin makes the input end 5px short of the date/time
	   row below it, creating a visible misalignment. Zero it out on xs. */
	#nameform {
		margin-right: 0 !important;
	}
}
body.dark-mode .panel-default > .panel-heading {
	color: var(--dark-mode-light-text-color);
}
/* Keep success/warning/danger panel heads colored — they rely on the
   contrasting background to signal state, and the flex layout above
   shouldn't force uppercase/tracking on them. */
.panel-success > .panel-heading,
.panel-warning > .panel-heading,
.panel-danger > .panel-heading,
.panel-info > .panel-heading {
	text-transform: none;
	letter-spacing: normal;
	font-size: inherit;
	font-weight: inherit;
	padding: 10px 15px;
	display: block;
}

/* 8. Empty-state helper. Use on any "no X to display" block as:
      <div class="empty-state">
         <i class="fa fa-inbox empty-state-icon"></i>
         <div class="empty-state-title">No topics yet</div>
         <div class="empty-state-text">Start one to break the ice.</div>
         <a class="btn btn-primary empty-state-cta" href="...">New Topic</a>
      </div>
      Works at any width. */
.empty-state {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	text-align: center;
	padding: 40px 20px;
	color: var(--light-mode-light-text-color);
}
.empty-state-icon {
	font-size: 48px;
	color: #c4c8cc;
	margin-bottom: 14px;
}
.empty-state-title {
	font-size: 17px;
	font-weight: 600;
	color: var(--light-mode-text-color);
	margin-bottom: 4px;
}
.empty-state-text {
	font-size: 14px;
	max-width: 320px;
	margin-bottom: 16px;
	line-height: 1.4;
}
.empty-state-cta {
	min-width: 160px;
}
body.dark-mode .empty-state {
	color: var(--dark-mode-light-text-color);
}
body.dark-mode .empty-state-icon {
	color: #4a4d51;
}
body.dark-mode .empty-state-title {
	color: var(--dark-mode-text-color);
}

/*
 * Bootstrap 5 parity overrides. Loaded only in the bs5 bundle, after
 * groupsio.css. The app CSS and body padding (60px) were designed around
 * Bootstrap 3 metrics; these rules restore them where Bootstrap 5 differs
 * (docs/specs/bootstrap5-migration.md). Delete at BS3 removal if the design
 * is retuned instead.
 */

/* BS3 navbars carry no vertical padding and declare min-height: 50px;
 * BS5's .5rem paddings make the bar 66px, sliding content (body
 * padding-top: 60px) underneath it. Zeroing the padding is what restores
 * the height — with it gone the bar sizes itself to 50.8px beside the
 * desktop nav links and 50px on a phone, matching BS3 at both. The floor
 * is BS3's declared 50px, not the 51px this rule used to carry: that was
 * the rendered desktop bar (50.8, rounded) used as a minimum, which held
 * the phone bar 1px above its BS3 twin, where the nav links driving the
 * extra 0.8px are hidden. */
.navbar-head {
	padding-top: 0;
	padding-bottom: 0;
	min-height: 50px;
}

/* BS3 floats packed the nav lists against the logo; BS5's navbar container
 * defaults to space-between, which floats the left list toward center.
 * Pack left, and push the right-side lists over with an auto margin. */
.navbar-head > .container-fluid {
	justify-content: flex-start;
}

.navbar-head .navbar-nav.navbar-right,
.navbar-head .navbar-nav.float-end {
	margin-left: auto;
	/* BS3 navbar-right pulls itself over the container padding so only
	 * the last link's own padding spaces it from the viewport edge. */
	margin-right: -0.75rem;
}

.navbar-head .navbar-nav .nav-link {
	padding: 0.9375rem;
	line-height: 1.25;
}

/* BS3 collapsed-navbar links were 10px 15px below the nav breakpoint. */
@media (max-width: 767.98px) {
	.navbar-head .navbar-nav .nav-link {
		padding: 0.625rem 0.9375rem;
	}
}

/* BS5's .navbar-nav is flex-direction: column until a navbar-expand-*
 * class switches it to row, and this list carries none — so the header's
 * two phone action icons stacked, doubling the bar to 100px and dropping
 * the search icon onto a second line. BS3 floated them side by side. */
.navbar-actions-xs {
	flex-direction: row;
}

/* The phone bottom tab bar. Its surface came from .navbar-default
 * (#f8f8f8, #e7e7e7) and its 1px top rule from .navbar-fixed-bottom's
 * border-width: 1px 0 0 — neither class exists in BS5, so the bar lost
 * its background and the rule separating it from the page. BS5's .navbar
 * also adds 0.5rem of vertical padding where BS3 had none and dropped
 * BS3's 50px min-height.
 *
 * Keyed on the app's own ids rather than the BS3 class names, so the
 * markup can shed them: the BS5 arm no longer emits either. */
#mobileSidebar .navbar {
	min-height: 50px;
	padding: 0;
	background-color: #f8f8f8;
	border-top: 1px solid #e7e7e7;
}

/* BS5's .navbar > .container centers its items; the tab row wants the
 * BS3 default of stretch, or the shorter "More" tab floats in the middle
 * of the row instead of sharing the others' top edge. */
#mobileSidebar .navbar > .container {
	align-items: stretch;
}

body.dark-mode #mobileSidebar .navbar {
	background-color: var(--dark-mode-primary-color);
	border-top-color: #000;
}

/* The soft-card surface (groupsio.css, keyed on .panel/.well): no border,
 * a 12px radius and a two-layer shadow instead of BS5's 1px outline and
 * 6px radius. The mirrors below cover the head and body of a card but
 * this is the card itself, so without it every converted card in the
 * tree reads as an outlined box rather than the app's soft card.
 * overflow: hidden is load-bearing — a colored .card-header sits at the
 * top edge and its square corners would otherwise escape the radius.
 * BS3 .panel also carried margin-bottom: 20px, which BS5 .card lacks,
 * collapsing stacked cards together. */
.card {
	margin-bottom: 20px;
	border: 0;
	border-radius: 12px;
	box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04), 0 1px 6px rgba(0, 0, 0, 0.04);
	overflow: hidden;
}

/* .well survives into the BS5 bundle because groupsio.css defines it, but
 * groupsio.css only restyles the surface (radius, shadow, background) —
 * the box metrics came from Bootstrap 3 itself and are gone, leaving the
 * text flush against the tinted edge. A class that survives only
 * partially is invisible to classcheck, which tests per class name. */
.well {
	min-height: 20px;
	padding: 19px;
	margin-bottom: 20px;
}

/* blockquote is the same partial survival as .well: groupsio.css supplies
 * its border and type but the padding was Bootstrap 3's, so quote text
 * sat flush against the 5px left border. */
blockquote {
	padding: 10px 20px;
}

.well-sm {
	padding: 9px;
}

.well-lg {
	padding: 24px;
}

/* BS3 .thumbnail, verbatim. BS5 dropped the class (its nearest kin,
 * .img-thumbnail, is image-only) and every site here is a container:
 * hashtag tiles, chat media, photo grids, RSVP cards. The class stays
 * until the Thumbnail component in the components doc is extracted.
 * groupsio.css keys .thumbnail.chat-preview-* on the name in both
 * bundles, which is a second reason it has to survive. :where() keeps
 * the box below the app's own tile rules (hashtag-box-* border colours)
 * that beat Bootstrap 3 by load order. */
:where(.thumbnail) {
	display: block;
	padding: 4px;
	margin-bottom: 20px;
	line-height: 1.42857143;
	background-color: #fff;
	border: 1px solid #ddd;
	border-radius: 4px;
	transition: border 0.2s ease-in-out;
}

.thumbnail > img,
.thumbnail a > img {
	display: block;
	max-width: 100%;
	height: auto;
	margin-right: auto;
	margin-left: auto;
}

a.thumbnail:hover,
a.thumbnail:focus,
a.thumbnail.active {
	border-color: #337ab7;
}

.thumbnail .caption {
	padding: 9px;
	color: #333333;
}

/* The .panel leftovers the components doc deliberately keeps on BS3
 * classes (the collapsable panels) took their 20px bottom margin from
 * Bootstrap 3's .panel, which BS5 has no equivalent of. groupsio.css
 * supplies their surface in both bundles but never their spacing. */
.panel {
	margin-bottom: 20px;
}

/* BS3 .page-header, verbatim. BS5 dropped the class and no utility
 * combination reproduces the 40/20 margins, so the remaining sites keep
 * it until the PageHeader component in the components doc is extracted.
 * The light border is BS3's own value in dark mode too — matching it is
 * parity; changing it would be a restyle. */
.page-header {
	padding-bottom: 9px;
	margin: 40px 0 20px;
	border-bottom: 1px solid #eee;
}

/* BS3 .dl-horizontal, verbatim, for the shared tabletemplates profile
 * rows (and account/groupprofile, paidmemberships, memberdetail) that keep
 * the class. groupsio.css's .about-grid dt/dd override the width and
 * margin at equal specificity and won under BS3 only by load order;
 * :where() keeps this rule below them so they still do. */
@media (min-width: 768px) {
	:where(.dl-horizontal) dt {
		float: left;
		width: 160px;
		clear: left;
		text-align: right;
		overflow: hidden;
		text-overflow: ellipsis;
		white-space: nowrap;
	}
	:where(.dl-horizontal) dd {
		margin-left: 180px;
	}
}
:where(.dl-horizontal) dd::before,
:where(.dl-horizontal) dd::after {
	display: table;
	content: " ";
}
:where(.dl-horizontal) dd::after {
	clear: both;
}

/* BS3's media object, verbatim. BS5 dropped it in favour of d-flex; the
 * shared tabletemplates GitHub column and the Dropzone preview rows keep
 * the classes (groupsio.css keys .dropzone.dropzone-multiple .media on
 * them). The .pull-* variants are not mirrored: converted pages have no
 * pull-* left to pair with them. */
.media {
	margin-top: 15px;
}
.media:first-child {
	margin-top: 0;
}
.media,
.media-body {
	overflow: hidden;
	zoom: 1;
}
.media-body {
	width: 10000px;
}
.media-right {
	padding-left: 10px;
}
.media-left {
	padding-right: 10px;
}
.media-left,
.media-right,
.media-body {
	display: table-cell;
	vertical-align: top;
}
.media-heading {
	margin-top: 0;
	margin-bottom: 5px;
}

/* groupsio.css pins the anchor in a default panel's title to the heading's
 * own colour and lays it out as a flex row (.panel-default > .panel-heading
 * .panel-title > a); the card classes miss it, so a hand-rolled collapse
 * toggle in a card title (tabletemplates' column editor) drew link-blue.
 * Scoped to headers without a contextual text-bg-*, as BS3's rule was
 * scoped to panel-default. cmd/admin carries the same rule inline. */
.card > .card-header:not([class*="text-bg-"]) .card-title > a,
.card > .card-header:not([class*="text-bg-"]) .card-title > a:hover,
.card > .card-header:not([class*="text-bg-"]) .card-title > a:focus {
	color: inherit;
	text-decoration: none;
	display: flex;
	align-items: center;
	justify-content: space-between;
	width: 100%;
}

/* BS3 modal widths, verbatim: 600px dialogs from 768px and 900px large
 * dialogs from 992px. BS5 defaults to 500px and 800px, which re-wrapped
 * the text of every converted modal (groupaddevent's Zoom meeting radios
 * broke onto two lines). BS5 applies the width from 576px, where BS3 was
 * still full width; a 600px cap is within a few px of that there. */
.modal {
	--bs-modal-width: 600px;
}
/* BS3 kept the dialog full width with 10px side margins until its 768px
 * breakpoint; BS5 caps and centres it from 576px, so with the 600px cap a
 * dialog on a 576-640px viewport would otherwise run edge to edge. */
@media (min-width: 576px) and (max-width: 767.98px) {
	.modal-dialog {
		max-width: none;
		margin: 10px;
	}
}
@media (min-width: 992px) {
	.modal-lg {
		--bs-modal-width: 900px;
	}
}

/* BS3 progress bar, via BS5's variables: a 20px #f5f5f5 track with 4px
 * corners and the BS3 primary fill at 12px text, plus BS3's 20px bottom
 * margin. BS5 draws 1rem on its secondary background in its own blue.
 * The Dropzone upload bars on files and photos are the converted sites. */
.progress {
	--bs-progress-height: 20px;
	--bs-progress-font-size: 12px;
	--bs-progress-bg: #f5f5f5;
	--bs-progress-border-radius: 4px;
	--bs-progress-box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.1);
	--bs-progress-bar-bg: #337ab7;
	margin-bottom: 20px;
}
.progress-bar {
	line-height: 20px;
	box-shadow: inset 0 -1px 0 rgba(0, 0, 0, 0.15);
}

/* BS3 heading <small>, verbatim: normal weight, #777, 65% of the heading
 * in h1-h3 and 75% in h4-h6. BS5 sizes every small at .875em and leaves
 * the heading's own weight and colour on it, so the "[See All]" beside
 * group home's Top Hashtags heading drew bold and full-size. */
h1 small, h2 small, h3 small, h4 small, h5 small, h6 small,
.h1 small, .h2 small, .h3 small, .h4 small, .h5 small, .h6 small,
h1 .small, h2 .small, h3 .small, h4 .small, h5 .small, h6 .small,
.h1 .small, .h2 .small, .h3 .small, .h4 .small, .h5 .small, .h6 .small {
	font-weight: 400;
	line-height: 1;
	color: #777;
}
h1 small, .h1 small, h2 small, .h2 small, h3 small, .h3 small,
h1 .small, .h1 .small, h2 .small, .h2 .small, h3 .small, .h3 .small {
	font-size: 65%;
}
h4 small, .h4 small, h5 small, .h5 small, h6 small, .h6 small,
h4 .small, .h4 .small, h5 .small, .h5 .small, h6 .small, .h6 .small {
	font-size: 75%;
}

/* Type-scale parity. The app's BS3-era metrics: line-height 1.428571429
 * (BS5 reboot uses 1.5) and the BS3 heading scale, expressed relatively per
 * the migration policy (all new font sizes in rem/em/unitless). */
body {
	line-height: 1.428571429;
}

/* h3 is 22px, not the stock BS3 24px: groupsio.css overrides it, and this
 * sheet loads after it, so the stock value would silently win. */
h1 { font-size: 2.25rem; }
h2 { font-size: 1.875rem; }
h3 { font-size: 1.375rem; }
h4 { font-size: 1.125rem; }
h5 { font-size: 0.875rem; }
h6 { font-size: 0.75rem; }

h1, h2, h3, h4, h5, h6 {
	line-height: 1.1;
}

/* BS3 heading margins: 20px above / 10px below for h1-h3, 10px both for
 * h4-h6; the BS5 reboot is 0 above / 8px below, tightening page flow.
 * Modal titles stay at BS3's zero — BS5's .modal-title only zeroes the
 * bottom, so the h4 top margin above would leak into modal headers. */
h1, h2, h3 {
	margin: 1.25rem 0 0.625rem;
}

h4, h5, h6 {
	margin: 0.625rem 0;
}

.modal-title {
	margin: 0;
}

/* Mirror of the soft-card heading design (groupsio.css section 6, keyed
 * on .panel-default > .panel-heading, which the BS5 card classes miss). */
.card > .card-header {
	background: transparent;
	border: 0 !important;
	padding: 1rem 1.125rem;
	font-size: 0.9375rem;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: 0.04em;
	color: #555;
	line-height: 1.4;
}

.card > .card-header .card-title,
.card > .card-header h1,
.card > .card-header h2,
.card > .card-header h3,
.card > .card-header h4 {
	font-size: inherit;
	font-weight: inherit;
	text-transform: inherit;
	letter-spacing: inherit;
	color: inherit;
	line-height: inherit;
	margin: 0;
	display: flex;
	align-items: center;
	justify-content: space-between;
}

/* groupsio.css keys the soft-card heading on .panel-default, so BS3's
 * variant panels kept plain colored heads (and it resets them explicitly
 * at "Keep success/warning/danger panel heads colored"). The mirror above
 * is keyed on .card > .card-header with no variant qualifier, so variant
 * headers need that exemption spelled out here. */
.card > .card-header:is(.text-bg-primary, .text-bg-success, .text-bg-info,
	.text-bg-warning, .text-bg-danger) {
	text-transform: none;
	letter-spacing: normal;
	font-size: inherit;
	font-weight: inherit;
	padding: 10px 15px;
	display: block;
}

.card > .card-header:is(.text-bg-primary, .text-bg-success, .text-bg-info,
	.text-bg-warning, .text-bg-danger) .card-title {
	display: block;
	margin: 0;
}

/* The contextual heading palette. BS5's text-bg-* is a solid brand fill
 * for every variant, but that is only what BS3 rendered for primary:
 * groupsio.css overrides success to a darker solid (#419641), and info,
 * warning and danger were BS3's pale tints with dark text. Measured off
 * the BS3 twin, not read off the Bootstrap 3 source, because of that
 * success override. primary needs no rule — text-bg-primary already
 * resolves to #337ab7 through --bs-primary-rgb above.
 *
 * Note the cards themselves carry no border-* utility: groupsio.css
 * gives every .panel `border: 0` as part of the soft-card design, so a
 * contextual card is borderless and only its head is colored. */
.card > .card-header.text-bg-success {
	background-color: #419641 !important;
	color: #fff !important;
}

.card > .card-header.text-bg-info {
	background-color: #d9edf7 !important;
	color: #31708f !important;
}

.card > .card-header.text-bg-warning {
	background-color: #fcf8e3 !important;
	color: #8a6d3b !important;
}

.card > .card-header.text-bg-danger {
	background-color: #f2dede !important;
	color: #a94442 !important;
}

/* A BS3 collapsable panel's toggle lived in .panel-heading, so it picked
 * up the soft-card section-label treatment above; the BS5 accordion has
 * its own header element and does not. Mirror the same typography onto
 * the toggle. Measured: BS3 renders these 15px/700/uppercase with 0.6px
 * tracking. */
.accordion-button {
	font-size: 0.9375rem;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: 0.04em;
}

/* BS5 tints the open header (--bs-accordion-active-bg is a primary
 * subtle) and underlines it with an inset shadow. BS3 left an expanded
 * .panel-heading looking exactly like a collapsed one, so hold both to
 * the resting values.
 *
 * The surface and metrics are the soft card again: a BS3 collapsable
 * accordion was .panel.panel-default inside .panel-group, so groupsio.css
 * gave it border: 0 and the shadow, BS3's .panel-group pinned the radius
 * to 4px, and the heading padding came out at 16px/18px. BS5 instead
 * draws a 1px outline with no shadow. */
.accordion {
	--bs-accordion-active-bg: var(--bs-accordion-btn-bg);
	--bs-accordion-active-color: var(--bs-accordion-btn-color);
	--bs-accordion-border-width: 0;
	--bs-accordion-border-radius: 4px;
	--bs-accordion-btn-padding-y: 1rem;
	--bs-accordion-btn-padding-x: 1.125rem;
}

.accordion-item {
	box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04), 0 1px 6px rgba(0, 0, 0, 0.04);
	overflow: hidden;
}

.accordion-button:not(.collapsed) {
	box-shadow: none;
}

/* BS5 rings the toggle with a 4px glow on any focus, and an anchor keeps
 * focus after a click, so the ring stayed on the header after opening and
 * closing it. BS3 drew nothing here. groupsio.css's own convention
 * (section 3, "Focus ring only for keyboard users via :focus-visible —
 * touch and click-focus stay quiet") is the right shape: quiet on click,
 * and the app's ring rather than BS5's #0d6efd for keyboard users. */
.accordion-button:focus {
	box-shadow: none;
}

.accordion-button:focus-visible {
	/* Inset, not the app's usual outset ring: the accordion item clips
	 * its children (overflow: hidden squares the header corners), so an
	 * outset ring on a flush-edged full-width button cannot paint. */
	box-shadow: inset 0 0 0 3px rgba(51, 122, 183, 0.25);
}

/* The BS5 accordion header is expected to be a heading element, and it
 * only zeroes margin-bottom — so the heading's top margin survives and
 * pads the item above the toggle, leaving the text sitting low in a
 * taller box. Same leak the .modal-title rule above exists to stop. */
.accordion-header {
	margin: 0;
}

/* The toggles are anchors, so the app's link-state colors reach them and
 * would repaint the header on hover and after a click leaves it focused.
 * BS3 pinned the equivalent .panel-title > a to inherit for exactly this
 * (groupsio.css, "Collapsable chevron"); same treatment, and the dark
 * pair has to be spelled out because body.dark-mode a:hover outspecifies
 * a single-class rule. */
.accordion-button,
.accordion-button:hover,
.accordion-button:focus {
	color: var(--bs-accordion-btn-color);
	text-decoration: none;
}

/* Mirror of the soft-card body padding (groupsio.css, keyed on
 * .panel-default .panel-body). */
.card .card-body {
	padding: 0.5rem 1.125rem 1rem;
}

@media (max-width: 767px) {
	.card .card-body {
		padding-left: 0.75rem;
		padding-right: 0.75rem;
	}

	.card > .card-header {
		padding-left: 0.75rem;
		padding-right: 0.75rem;
	}
}

/* BS3 badge/label parity. Zero-specificity defaults (:where) so custom
 * classes (hashtag-label-*, member colors) and text-bg-* utilities win as
 * they did when groupsio.css loaded after Bootstrap 3. A plain .badge is a
 * former BS3 count badge and keeps the grey pill shape; a badge carrying a
 * color (a bg- utility, a hashtag-label class, or an inline background) is
 * a former BS3 label and gets the label geometry. */
:where(.badge) {
	background-color: #777;
	color: #fff;
}

/* Geometry needs normal specificity to beat BS5's own .badge rule. The
 * colour classes only set colours, but group home's two chip classes
 * (grouphome-tag-chip, grouphome-hashtag-chip) set their own display,
 * padding and radius at (0,1,0) and won under BS3 by load order, so the
 * label-geometry rule leaves them out. groupsio.css's .subject
 * .hashtag-btn (display: inline-block on phones) has the same shape and
 * will need the same exclusion when the messages wave converts. */
.badge {
	border-radius: 0.625rem;
	padding: 0.1875rem 0.4375rem;
	vertical-align: middle;
}

.badge[class*="bg-"],
.badge[class*="hashtag-label-"]:not(.grouphome-tag-chip):not(.grouphome-hashtag-chip),
.badge[style*="background"] {
	display: inline;
	border-radius: 0.25em;
	padding: 0.2em 0.6em 0.3em;
	vertical-align: baseline;
}

/* BS3 hid an empty label outright (.label:empty). Bootstrap 5 has the same
 * rule for .badge, but the label-geometry rule above comes later at equal or
 * higher specificity (the :not() chain reaches (0,4,0)) and would otherwise
 * restore display: inline, leaving an empty coloured pill. */
.badge:empty {
	display: none !important;
}

/* Custom components below were written in rem against Bootstrap 3's 10px
 * html font-size; BS5 leaves the root at 16px, so compensate (x0.625). */
.drawer-header,
.drawer-content {
	padding: 0.9375rem;
}

.chat-emoji {
	font-size: 0.875rem;
}

.dropzone {
	border-radius: 0.234375rem;
}

.dropzone .dz-remove {
	right: 0.3125rem;
	top: 0.3125rem;
	width: 1.25rem;
	height: 1.25rem;
	line-height: 1.25rem;
}

.dropzone .dz-message {
	padding: 3.125rem 1.25rem;
}

.dropzone.dropzone-multiple .media:first-child {
	margin-top: 1.125rem;
}

.dropzone.dropzone-multiple .dz-image {
	margin-right: 0.625rem;
}

.navbar-vertical .dropdown-indicator {
	padding-right: 0.625rem !important;
}

.dropdown-indicator:after {
	height: 0.5rem;
	width: 0.5rem;
}

/* BS3 button text metrics on every variant: 14px at the 1.42 line-height,
 * which is where the 34px button height (matching the form controls)
 * comes from. BS5 buttons are 16px at 1.5. */
.btn {
	font-size: 0.875rem;
	line-height: 1.428571429;
}

/* BS3 .btn-toolbar spacing, verbatim: 5px between the groups it lays out,
 * with the first one pulled back so the toolbar stays flush left. BS5's
 * toolbar is a flex container with no gap, so its groups touched (the
 * calendar's prev/next, Today and date-picker buttons). ms-auto on a
 * group still wins, since the utility is !important. */
.btn-toolbar {
	margin-left: -5px;
}
.btn-toolbar > .btn,
.btn-toolbar > .btn-group,
.btn-toolbar > .input-group {
	margin-left: 5px;
}

/* BS3 .btn-xs box, verbatim (bootstrap.css .btn-xs). groupsio.css keeps
 * only its 12px font size, so under BS5 the button otherwise takes .btn's
 * own padding and draws a third taller than its BS3 twin — two stacked
 * btn-xs buttons in a narrow column were 7px lower on groupeditphoto.
 * cmd/admin carries the same rule inline in adminbase.qtpl. */
.btn-xs {
	padding: 1px 5px;
	line-height: 1.5;
	border-radius: 3px;
}

/* The app's btn-default is light grey (#ccc, dark text; groupsio.css:808);
 * converted pages emit btn-secondary, which BS5 paints dark slate. Repaint
 * it to the app palette via the button variables, light and dark mode. */
.btn-secondary {
	--bs-btn-color: #333;
	--bs-btn-bg: #ccc;
	--bs-btn-border-color: #ccc;
	--bs-btn-hover-color: #292929;
	--bs-btn-hover-bg: #bbb;
	--bs-btn-hover-border-color: #bbb;
	--bs-btn-active-color: #333;
	--bs-btn-active-bg: #bbb;
	--bs-btn-active-border-color: #b3b3b3;
	--bs-btn-disabled-color: #333;
	--bs-btn-disabled-bg: #ccc;
	--bs-btn-disabled-border-color: #ccc;
}

body.dark-mode .btn-secondary {
	--bs-btn-color: var(--dark-mode-text-color);
	/* Set directly as well as through the variable: BS5 applies the
	 * variable from .btn at (0,1,0), which groupsio.css's body.dark-mode a
	 * (0,1,2) beats on anchor buttons, leaving them link-blue on grey at
	 * 3.9:1. groupsio.css's own body.dark-mode .btn-default sets color at
	 * (0,2,0), which is what kept BS3's anchor buttons legible. */
	color: var(--dark-mode-text-color);
	--bs-btn-bg: #444;
	--bs-btn-border-color: #444;
	--bs-btn-hover-color: var(--dark-mode-text-color);
	--bs-btn-hover-bg: #555;
	--bs-btn-hover-border-color: #444;
	--bs-btn-active-bg: #555;
	--bs-btn-active-border-color: #444;
}

/* BS3 text color and contextual palette. BS5's body text is #212529 and its
 * contextual colors shifted; the text-bg- and bg- utilities read the rgb
 * variables, so remap those to the BS3 values. Buttons and links are
 * already covered by the app CSS and the rules above. */
body {
	color: #333;
	--bs-body-color: #333;
}

:root {
	--bs-body-color: #333;
}

/* The app link color (groupsio.css styles `a` directly, but BS5 components
 * like .btn-link and .pagination read the link variables instead, and a
 * class selector beats the plain `a` rule). Hover is BS3's compiled
 * a:hover value, which the app never overrode. */
:root {
	--bs-link-color: #2f6fa7;
	--bs-link-color-rgb: 47, 111, 167;
	--bs-link-hover-color: #23527c;
	--bs-link-hover-color-rgb: 35, 82, 124;
}

/* BS3 link decoration: bare at rest, underlined on hover (BS5 underlines
 * at rest). BS3 kept its interactive components underline-free on hover;
 * the higher-specificity a:hover would otherwise beat their class rules. */
a {
	text-decoration: none;
}

a:hover,
a:focus {
	text-decoration: underline;
}

a.list-group-item:hover,
a.list-group-item:focus,
.nav-link:hover,
.nav-link:focus,
.dropdown-item:hover,
.dropdown-item:focus,
.btn:hover,
.btn:focus,
a.badge:hover,
a.badge:focus {
	text-decoration: none;
}

/* BS3's .tooltip-inner declared white text on its own background, and
 * groupsio.css keeps only the background (rgb(36,37,38) on .tooltip-inner,
 * with an arrow rule aimed at BS3's .tooltip-arrow element). BS5 reads the
 * text colour from --bs-tooltip-color, which defaults to --bs-body-bg and so
 * turns dark in dark mode, and draws the arrow from --bs-tooltip-bg on
 * .tooltip-arrow::before, which the app's rule never reaches. Pin both
 * variables to the app's bubble colours so text and arrow match it in either
 * theme. */
.tooltip {
	--bs-tooltip-color: #fff;
	--bs-tooltip-bg: rgb(36,37,38);
}

/* BS3 nav-tabs: #555 active text, #ddd borders, 4px corners. */
.nav-tabs {
	--bs-nav-tabs-link-active-color: #555;
	--bs-nav-tabs-border-color: #ddd;
	--bs-nav-tabs-link-active-border-color: #ddd #ddd #fff;
	--bs-nav-tabs-border-radius: 0.25rem;
}

/* BS3 pagination palette: #ddd borders, #eee hover, #777 disabled text,
 * BS3-primary active. The link color itself follows --bs-link-color. */
.pagination {
	--bs-pagination-border-color: #ddd;
	--bs-pagination-hover-color: #23527c;
	--bs-pagination-hover-bg: #eee;
	--bs-pagination-hover-border-color: #ddd;
	--bs-pagination-focus-color: #23527c;
	--bs-pagination-focus-bg: #eee;
	/* BS5's keyboard focus ring is its own blue; the accordion and the
	 * app's inputs use the app primary, so the page links do too. */
	--bs-pagination-focus-box-shadow: 0 0 0 0.25rem rgba(51, 122, 183, 0.25);
	--bs-pagination-disabled-color: #777;
	--bs-pagination-disabled-bg: #fff;
	--bs-pagination-disabled-border-color: #ddd;
	--bs-pagination-active-bg: #337ab7;
	--bs-pagination-active-border-color: #337ab7;
}

:root {
	--bs-primary-rgb: 51, 122, 183;
	--bs-success-rgb: 92, 184, 92;
	--bs-info-rgb: 91, 192, 222;
	--bs-warning-rgb: 240, 173, 78;
	--bs-danger-rgb: 217, 83, 79;
	--bs-secondary-rgb: 119, 119, 119;
}

/* BS3 set the contextual alert palette on .alert-<variant> itself, so the
 * class colored anything it was put on — including bare spans used as
 * inline highlights. BS5's .alert-<variant> only declares --bs-alert-*
 * variables, which nothing reads unless .alert is also present, so those
 * spans lose their background and text color entirely. Restore the BS3
 * declarations; real .alert blocks get the same values, which is the
 * BS3 palette they had. Dark mode needs no line here — groupsio.css's
 * body.dark-mode .alert-* rules outspecify these and ship in both
 * bundles. */
.alert-success {
	color: #3c763d;
	background-color: #dff0d8;
	border-color: #d6e9c6;
}

.alert-info {
	color: #31708f;
	background-color: #d9edf7;
	border-color: #bce8f1;
}

.alert-warning {
	color: #8a6d3b;
	background-color: #fcf8e3;
	border-color: #faebcc;
}

.alert-danger {
	color: #a94442;
	background-color: #f2dede;
	border-color: #ebccd1;
}

/* BS3 labels were always white-on-color; BS5 bakes dark text onto the
 * info/warning variants. Scoped to badges: the Panel component also emits
 * text-bg-* (on cards), and BS3 panels kept dark body text, so an
 * unscoped rule puts white text on an orange card body. */
.badge.text-bg-info,
.badge.text-bg-warning {
	color: #fff !important;
}

/* BS3 text-* utilities used the dark emphasis palette, not the brand
 * palette the rgb variables above feed to text-bg-*; !important matches
 * the BS5 utility rules these must beat. */
.text-success {
	color: #3c763d !important;
}

.text-info {
	color: #31708f !important;
}

.text-warning {
	color: #8a6d3b !important;
}

.text-danger {
	color: #a94442 !important;
}


/* BS5 tables read --bs-emphasis-color (black) and their own striping
 * variables; restore the BS3 values. */
:root {
	--bs-emphasis-color: #333;
	--bs-emphasis-color-rgb: 51, 51, 51;
}

.table {
	--bs-table-color: #333;
	/* BS3 cells are transparent; BS5 paints every cell --bs-table-bg
	 * (white), which would cover row backgrounds set on the tr — the
	 * member row-color feature paints there. */
	--bs-table-bg: transparent;
	/* groupsio.css stripes on the tr (odd rows the primary colour, even
	 * rows the highlight colour), but BS5 paints its striped colour on
	 * every odd cell, over the row. Give it the odd-row colour so the
	 * even rows' highlight stays the contrasting stripe, as under BS3. */
	--bs-table-striped-bg: var(--light-mode-primary-color);
	--bs-table-hover-bg: #f5f5f5;
	--bs-table-border-color: #ddd;
}

.table > :not(caption) > * > * {
	border-color: #ddd;
}

/* BS3 list-group metrics: 15px side padding (BS5 uses 1rem), a 20px
 * bottom margin (BS5 has none; the chat mention popup is an absolutely
 * positioned list-group whose bottom: 50px measures the margin box, so
 * without it the popup sat 20px lower and overlapped the composer), and
 * #555 text on anchor and button items only — BS3 declared the colour on
 * a.list-group-item/button.list-group-item, so a plain <li> item kept
 * the inherited body colour, as groupsubgrouplist's rows do. */
.list-group {
	--bs-list-group-item-padding-x: 0.9375rem;
	margin-bottom: 20px;
}

a.list-group-item,
button.list-group-item {
	--bs-list-group-color: #555;
}

/* The margin-layout chrome drops the .row class from #mainrow under BS5
 * (BS5 rows are flex and break the fixed-sidebar layout). BS3 relied on
 * the row's negative margin canceling the container-fluid padding to put
 * the sidebar flush against the viewport edge; restore that. On pages
 * where #mainrow keeps .row, this matches the BS5 row margin exactly. */
#mainrow {
	margin-left: -0.75rem;
	margin-right: -0.75rem;
}

/* BS3 list-group items overlap by 1px (margin-bottom: -1px border
 * collapse), which sets the sidebar's vertical rhythm. Scoped to the
 * sidebar because its items are borderless: bordered BS5 list-groups
 * collapse by zeroing border-top instead, and a negative margin there
 * would hide the separator borders. */
#groupsidebar .list-group-item {
	margin-bottom: -1px;
}

/* The chrome's #maincontent-column carries col-xs-12, which supplied its
 * 15px side gutters under BS3; the -xs- grid tier does not exist in BS5. */
.maincontent-column {
	padding-left: 0.9375rem;
	padding-right: 0.9375rem;
}

/* The chat column keeps col-xs-12 for the app's own rules; under BS3 that
 * class also gave it a 15px left gutter from 992px up (groupsio.css zeroes
 * only the right one), so the message list and composer sat 15px in from
 * the sidebar. Below 992px groupsio.css's own col-xs-12 rule sets 5px in
 * both bundles, and the phone rule zeroes it. */
@media (min-width: 992px) {
	.maincontent-chat-column {
		padding-left: 0.9375rem;
	}
}

/* No live consumer: the keyboard-shortcuts modal that needed this now
 * emits col-3/col-9 under BS5, and the remaining col-xs-3/9 sites are on
 * unconverted pages, which load the BS3 bundle instead. Retained as a
 * safety net for pages that convert without branching their -xs- columns. */
.col-xs-3 {
	width: 25%;
	padding: 0 0.9375rem;
}

.col-xs-9 {
	width: 75%;
	padding: 0 0.9375rem;
}

/* BS3 responsive/print hiding utilities still present in shared markup
 * (BS5 renamed them to d-* forms). BS3 breakpoints: xs <768, sm 768-991,
 * md 992-1199, lg >=1200. */
@media print {
	.hidden-print {
		display: none !important;
	}
}

@media (max-width: 767.98px) {
	.hidden-xs {
		display: none !important;
	}
}

@media (min-width: 768px) and (max-width: 991.98px) {
	.hidden-sm {
		display: none !important;
	}
}

@media (min-width: 992px) and (max-width: 1199.98px) {
	.hidden-md {
		display: none !important;
	}
}

@media (min-width: 1200px) {
	.hidden-lg {
		display: none !important;
	}
}

/* BS3's .table-responsive carried a phone block Bootstrap 5 dropped while
 * keeping the class name: below 768px every cell went nowrap, so a wide
 * table stayed one line per row and scrolled sideways instead of wrapping
 * each row over a dozen screen lines. Reported on beta the evening the
 * admin pages shipped -- the activity log was the page that hurt.
 * classcheck's declaration diff deliberately skips classes BS5 kept, which
 * is exactly where this hid. Values are BS3's own phone block. */
@media screen and (max-width: 767.98px) {
	/* No border here: BS3 drew 1px #ddd around phone tables but
	 * groupsio.css zeroes it, and this sheet loads after groupsio.css,
	 * so carrying BS3's value would paint a border the app removed. */
	.table-responsive {
		width: 100%;
		margin-bottom: 15px;
		overflow-y: hidden;
	}

	.table-responsive > .table {
		margin-bottom: 0;
	}

	.table-responsive > .table > thead > tr > th,
	.table-responsive > .table > tbody > tr > th,
	.table-responsive > .table > tfoot > tr > th,
	.table-responsive > .table > thead > tr > td,
	.table-responsive > .table > tbody > tr > td,
	.table-responsive > .table > tfoot > tr > td {
		white-space: nowrap;
	}
}

/* BS3 text alignment utilities (BS5 renamed them text-start/text-end). */
.text-left {
	text-align: left;
}

.text-right {
	text-align: right;
}

/* The BS3 caret triangle, for toggles that render an explicit caret
 * span; BS5 draws its own caret via .dropdown-toggle::after, so suppress
 * that when a span is present to avoid doubling. */
.caret {
	display: inline-block;
	width: 0;
	height: 0;
	margin-left: 2px;
	vertical-align: middle;
	border-top: 4px dashed;
	border-right: 4px solid transparent;
	border-left: 4px solid transparent;
}

.dropup .caret {
	border-top: 0;
	border-bottom: 4px dashed;
}

.dropdown-toggle:has(.caret)::after {
	display: none;
}

/* BS3 drew a caret only where the markup carried a .caret span; BS5 draws
 * one on every .dropdown-toggle via ::after, so icon-only toggles (the
 * chat composer's "+" menu, the wiki "..." menu) grew a caret they never
 * had. Toggles that want a caret keep their span, styled above. */
.dropdown-toggle::after,
.dropup .dropdown-toggle::after,
.dropend .dropdown-toggle::after,
.dropstart .dropdown-toggle::before {
	display: none;
}

/* BS3 breadcrumb bar (BS5 breadcrumbs are bare): grey rounded strip with
 * #ccc dividers at 5px spacing plus the nbsp BS3 put after the slash. The
 * app's margin-bottom, link colors, active color, and dark-mode variants key
 * on .breadcrumb in groupsio.css and apply as-is. */
.breadcrumb {
	padding: 0.5rem 0.9375rem;
	background-color: #f5f5f5;
	border-radius: 0.25rem;
	--bs-breadcrumb-divider-color: #ccc;
	--bs-breadcrumb-divider: "/\00a0";
	--bs-breadcrumb-item-padding-x: 0.3125rem;
}

/* groupsio.css forces display:inline-block !important on .scroll-breadcrumb,
 * which under BS3 was harmless because .breadcrumb > li was itself
 * inline-block. A BS5 .breadcrumb-item has no display of its own and relies on
 * the list being flex, so the override left the crumbs stacking one per line.
 * inline-flex rather than flex to keep the inline-block box the app asked for.
 * !important to reach past the app's own. nowrap because the app
 * scrolls .breadcrumb-container horizontally: under BS3 the crumbs stayed on
 * one line and the container clipped and scrolled them; a wrapping flex row
 * would stack them instead. */
.breadcrumb.scroll-breadcrumb {
	display: inline-flex !important;
	flex-wrap: nowrap;
}

/* BS3 dropdown metrics: #333 links with 3px 20px padding, #f5f5f5
 * hover, and the BS3 primary for active items. No font-size here: the
 * app sets .dropdown-menu to 16px in groupsio.css, which matches the
 * BS5 default. */
.dropdown-menu {
	--bs-dropdown-link-color: #333;
	--bs-dropdown-link-hover-color: #262626;
	--bs-dropdown-link-hover-bg: #f5f5f5;
	--bs-dropdown-link-active-color: #fff;
	--bs-dropdown-link-active-bg: #337ab7;
	--bs-dropdown-item-padding-x: 1.25rem;
	--bs-dropdown-item-padding-y: 0.1875rem;
}

/* BS3's dropdown item box for raw <li><a> menus that kept the BS3 shape
 * without a dropdown-item class (several groupadmin and group-tab menus).
 * BS5 puts every item declaration on .dropdown-item, so a bare anchor was
 * inline, flush left, wrapping and without a hover. Colour is not set
 * here: groupsio.css pins it (#333 !important in light mode, its own
 * dark-mode rules), and :where() keeps this below those rules. */
.dropdown-menu > li > :where(a:not(.dropdown-item)) {
	display: block;
	padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);
	clear: both;
	font-weight: 400;
	line-height: 1.42857143;
	white-space: nowrap;
	text-decoration: none;
}
.dropdown-menu > li > :where(a:not(.dropdown-item)):hover,
.dropdown-menu > li > :where(a:not(.dropdown-item)):focus {
	background-color: var(--bs-dropdown-link-hover-bg);
}

/* BS3 structural styles for raw .checkbox/.radio wrappers not yet converted
 * to the form-check component; the migration keeps some raw leftovers
 * (docs/specs/bootstrap5-migration.md), which have no styling in BS5. */
.checkbox,
.radio {
	position: relative;
	display: block;
	margin-top: 0.625rem;
	margin-bottom: 0.625rem;
}

.checkbox label,
.radio label {
	min-height: 1.25rem;
	padding-left: 1.25rem;
	margin-bottom: 0;
	font-weight: 400;
	cursor: pointer;
}

.checkbox input[type="checkbox"],
.checkbox-inline input[type="checkbox"],
.radio input[type="radio"],
.radio-inline input[type="radio"] {
	position: absolute;
	margin-left: -1.25rem;
	margin-top: 0.25rem;
}

.checkbox + .checkbox,
.radio + .radio {
	margin-top: -0.3125rem;
}

.checkbox-inline,
.radio-inline {
	position: relative;
	display: inline-block;
	padding-left: 1.25rem;
	margin-bottom: 0;
	font-weight: 400;
	vertical-align: middle;
	cursor: pointer;
}

.checkbox-inline + .checkbox-inline,
.radio-inline + .radio-inline {
	margin-top: 0;
	margin-left: 0.625rem;
}

/* BS3 form controls: 14px #555 text at the 1.42 line-height (the 34px
 * control height falls out) with #999 placeholders; the small variants
 * are 12px. BS5 renders controls at 16px in the body color. The -sm
 * padding override stays off form-select-sm, whose right padding
 * reserves room for the chevron. */
.form-control,
.form-select {
	font-size: 0.875rem;
	line-height: 1.428571429;
	color: #555;
}

.form-control::placeholder {
	color: #999;
}

.form-control-sm {
	padding: 0.3125rem 0.625rem;
}

.form-control-sm,
.form-select-sm {
	font-size: 0.75rem;
	line-height: 1.5;
}

/* The app's control design (groupsio.css section 3: 10px corners, the
 * #d6d9de border, no inset shadow, the brand border on click-focus and a
 * ring only for keyboard focus) is keyed on the input types, bare
 * `select` and .form-control. A converted page's select carries
 * .form-select instead, and BS5's own .form-select rule outspecifies the
 * bare `select` selector, so those selects drew BS5's 6px corners and
 * #dee2e6 border beside the page's 10px text inputs, and BS5's blue glow
 * on focus (beta #41139). The same declarations, on the BS5 name. */
.form-select {
	border-radius: 10px;
	border-color: #d6d9de;
	box-shadow: none;
}

.form-select:focus {
	outline: none;
	box-shadow: none;
	border-color: #337ab7;
}

.form-select:focus-visible {
	box-shadow: 0 0 0 3px rgba(51, 122, 183, 0.25);
	border-color: #337ab7;
}

/* BS3 form-group spacing and help-block hint styling, for raw leftovers
 * (e.g. the colorpicker wrappers) that the sweeps keep on BS3 classes. */
.form-group {
	margin-bottom: 0.9375rem;
}

/* The margins are the app's zeroes, not Bootstrap 3's 5px/10px:
 * groupsio.css zeroes them and loads after Bootstrap in the BS3 bundle,
 * so a BS3 page renders no margin here and this sheet, loading last,
 * would otherwise reintroduce spacing the app had removed. */
.help-block {
	display: block;
	margin-top: 0;
	margin-bottom: 0;
	color: #737373;
}

/* The FormRow component's BS5 arm emits .form-text where its BS3 arm emitted
 * .help-block, and BS5 shrinks .form-text to .875em in its own muted grey.
 * Converted pages carry both -- componentized hints and raw leftovers -- so
 * without this the same page renders help text at two sizes in two colours.
 * Match the .help-block above, which is what the BS3 page rendered. The colour
 * comes from groupsio.css, which lists .form-text beside .help-block in its
 * light and dark rules. */
.form-text {
	display: block;
	font-size: 1rem;
	line-height: 1.42857143;
	margin-top: 0;
}

/* Bootstrap 3's reboot bolds every label; Bootstrap 5 dropped that and its
 * .form-label declares only a margin, so the FormRow component's BS5 arm left
 * every form label on a converted page at regular weight. BS3's own 700, and
 * the margin it paired with it. */
.form-label {
	font-weight: 700;
	margin-bottom: 0.3125rem;
}

/* Same loss for the labels the sweeps left as raw markup: BS3's reboot bolded
 * every label, BS5's bolds none, so a converted page's page-owned labels went
 * light alongside the componentized ones. BS3 exempted the labels inside a
 * checkbox or radio, whose BS5 equivalent is .form-check-label. */
label {
	font-weight: 700;
	margin-bottom: 0.3125rem;
}

.form-check-label {
	font-weight: 400;
	margin-bottom: 0;
	cursor: pointer;
}

/* BS5 paints a checked form-check control in its own #0d6efd, and rings any
 * focused one with an #86b7fe border and a #0d6efd glow. The native controls
 * the raw leftovers still render take the brand blue from groupsio.css's
 * accent-color rule, so a page carrying both showed two blues. Focus follows
 * groupsio.css's convention (section 3): quiet on click, the app's ring for
 * keyboard users. :checked is declared last so a focused checked control
 * keeps the brand border. */
.form-check-input:focus {
	border-color: var(--bs-border-color);
	box-shadow: none;
}

.form-check-input:focus-visible {
	box-shadow: 0 0 0 3px rgba(51, 122, 183, 0.25);
}

.form-check-input:checked {
	background-color: #337ab7;
	border-color: #337ab7;
}

/* The Members page filter menu insets its checkboxes 20px from the menu
 * edges, which the raw BS3 wrappers carried as inline padding. The
 * form-check component has no style hook, and its own padding-left is
 * what positions the control (the input floats back into it), so the
 * inset is added on top of that. Direct children only: the member-label
 * filters further down sit inside a div that already carries the inset. */
#filterItems > .form-check {
	padding-left: calc(1.5em + 20px);
	padding-right: 20px;
}

/* BS3's .input-group-addon, whose BS5 name is .input-group-text: BS5 uses its
 * own lighter greys and a 6px radius where BS3 had #eee on #ccc at 4px. */
.input-group-text {
	color: #555;
	background-color: #eee;
	border-color: #ccc;
	border-radius: 0.25rem;
}

/* BS3's Glyphicons Halflings font, which Bootstrap 5 dropped. groupsio.css
 * draws the collapsable-panel chevron from it (content "\e114"/"\e080") and
 * bootstrap-colorselector.css the selected-swatch check ("\e013"); without the
 * face both render as a missing-glyph box. Same src set BS3 declared, minus
 * the IE-only eot/svg entries, whose browsers cannot run this bundle anyway.
 * The /fonts/ route serves content/web/bootstrap/fonts under both bundles. */
@font-face {
	font-family: 'Glyphicons Halflings';
	src: url(../fonts/glyphicons-halflings-regular.woff2) format('woff2'), url(../fonts/glyphicons-halflings-regular.woff) format('woff'), url(../fonts/glyphicons-halflings-regular.ttf) format('truetype');
}

/* The icon markup the bundled bootstrap-fileinput still emits names
 * Glyphicons: the zoom dialog's prev/next arrows, header toggles and
 * close, the browse/remove/cancel/upload buttons and the per-file action
 * and status icons. BS3 drew each from .glyphicon plus a per-icon ::before
 * codepoint; BS5 has neither, so every one of those buttons rendered
 * empty. BS3's base rule and the codepoints for exactly the icons the
 * plugin emits. */
.glyphicon {
	position: relative;
	top: 1px;
	display: inline-block;
	font-family: 'Glyphicons Halflings';
	font-style: normal;
	font-weight: 400;
	line-height: 1;
	-webkit-font-smoothing: antialiased;
	-moz-osx-font-smoothing: grayscale;
}
.glyphicon-remove::before { content: "\e014"; }
.glyphicon-zoom-in::before { content: "\e015"; }
.glyphicon-trash::before { content: "\e020"; }
.glyphicon-file::before { content: "\e022"; }
.glyphicon-download::before { content: "\e026"; }
.glyphicon-upload::before { content: "\e027"; }
.glyphicon-repeat::before { content: "\e030"; }
.glyphicon-move::before { content: "\e068"; }
.glyphicon-plus-sign::before { content: "\e081"; }
.glyphicon-ok-sign::before { content: "\e084"; }
.glyphicon-ban-circle::before { content: "\e090"; }
.glyphicon-resize-full::before { content: "\e096"; }
.glyphicon-exclamation-sign::before { content: "\e101"; }
.glyphicon-folder-open::before { content: "\e118"; }
.glyphicon-resize-vertical::before { content: "\e119"; }
.glyphicon-fullscreen::before { content: "\e140"; }
.glyphicon-hourglass::before { content: "\231b"; }
.glyphicon-triangle-right::before { content: "\e250"; }
.glyphicon-triangle-left::before { content: "\e251"; }

/* The plugin's zoom-dialog close button also carries BS5's .btn-close
 * name, which shrinks it to a 1em box and paints its own SVG cross over
 * the glyph. Give it back the button box its three siblings have. */
.kv-zoom-actions .btn-close {
	width: auto;
	height: auto;
	padding: 0.25rem 0.5rem;
	background-image: none;
	opacity: 1;
}

/* BS3's .has-error, which Bootstrap 5 replaced with .is-invalid on the
 * control. Converted pages emit is-invalid, but the shared branched templates
 * (tabletemplates' 24 form-group wrappers, the editor wrapper) keep the raw
 * BS3 wrapper in both arms, so the error state needs the BS3 treatment here.
 * Values are BS3's own declarations; groupsio.css never restyled has-error.
 * The BS5-arm names (form-label, form-text, form-select) are listed beside
 * their BS3 counterparts, the way groupsio.css pairs help-block/form-text. */
.has-error .control-label,
.has-error .form-label,
.has-error .help-block,
.has-error .form-text,
.has-error .checkbox label,
.has-error .radio label,
.has-error .form-check-label {
	color: #a94442;
}

.has-error .form-control,
.has-error .form-select {
	border-color: #a94442;
	box-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.075);
}

.has-error .form-control:focus,
.has-error .form-select:focus {
	border-color: #843534;
	box-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.075), 0 0 6px #ce8483;
}

/* BS3 gave a paragraph 10px of bottom margin; BS5's reboot gives it 1rem. The
 * extra 6px compounds down a page and was the largest single source of
 * vertical drift left between the two renderings.
 *
 * The matching BS3 metric for .checkbox/.radio (10px above and below, already
 * mirrored above for the raw leftovers) is deliberately NOT applied to
 * .form-check. BS5's box is structurally different -- it carries padding that
 * used to sit on the label -- so measuring it made the drift markedly worse:
 * 149 deltas against 89 with no rule at all, over the same four pages. A BS3
 * value only transfers where the box is the same. */
p {
	margin-bottom: 0.625rem;
}

/* BS3 button variant palette (btn-secondary handled above). */
.btn-primary {
	--bs-btn-bg: #337ab7;
	--bs-btn-border-color: #2e6da4;
	--bs-btn-hover-bg: #286090;
	--bs-btn-hover-border-color: #204d74;
	--bs-btn-active-bg: #286090;
	--bs-btn-active-border-color: #204d74;
	--bs-btn-disabled-bg: #337ab7;
	--bs-btn-disabled-border-color: #2e6da4;
}

.btn-success {
	--bs-btn-bg: #5cb85c;
	--bs-btn-border-color: #4cae4c;
	--bs-btn-hover-bg: #449d44;
	--bs-btn-hover-border-color: #398439;
	--bs-btn-active-bg: #449d44;
	--bs-btn-active-border-color: #398439;
}

.btn-info {
	--bs-btn-color: #fff;
	--bs-btn-bg: #5bc0de;
	--bs-btn-border-color: #46b8da;
	--bs-btn-hover-color: #fff;
	--bs-btn-hover-bg: #31b0d5;
	--bs-btn-hover-border-color: #269abc;
	--bs-btn-active-color: #fff;
	--bs-btn-active-bg: #31b0d5;
	--bs-btn-active-border-color: #269abc;
}

.btn-warning {
	--bs-btn-color: #fff;
	--bs-btn-bg: #f0ad4e;
	--bs-btn-border-color: #eea236;
	--bs-btn-hover-color: #fff;
	--bs-btn-hover-bg: #ec971f;
	--bs-btn-hover-border-color: #d58512;
	--bs-btn-active-color: #fff;
	--bs-btn-active-bg: #ec971f;
	--bs-btn-active-border-color: #d58512;
}

.btn-danger {
	--bs-btn-bg: #d9534f;
	--bs-btn-border-color: #d43f3a;
	--bs-btn-hover-bg: #c9302c;
	--bs-btn-hover-border-color: #ac2925;
	--bs-btn-active-bg: #c9302c;
	--bs-btn-active-border-color: #ac2925;
}

/* BS3 img-responsive, still emitted by shared components (e.g. the
 * member-data image columns); BS5 renamed it img-fluid. */
.img-responsive {
	display: block;
	max-width: 100%;
	height: auto;
}

/* Dark mode. The app's dark rules in groupsio.css key on the BS3 class
 * names (.panel-*, .close, .form-control) and set body color/background
 * as properties, never the BS5 variables — but BS5 component var chains
 * (table striping via --bs-body-color, card/modal backgrounds via
 * --bs-body-bg) read the variables. Remap them, then mirror the rules
 * groupsio.css keys on BS3 classes onto the BS5 class names. */
body.dark-mode {
	--bs-body-color: var(--dark-mode-text-color);
	--bs-body-bg: var(--dark-mode-body-color);
	--bs-emphasis-color: var(--dark-mode-text-color);
}
body.dark-mode .table {
	--bs-table-color: var(--dark-mode-text-color);
	/* Same shape as the light-mode block: the odd-row colour for BS5's
	 * cell-level stripe (the highlight colour here would match the even
	 * rows and erase the alternation), and groupsio.css's dark hover
	 * colour, which BS5's cell painting would otherwise cover. */
	--bs-table-striped-bg: var(--dark-mode-primary-color);
	--bs-table-hover-bg: var(--dark-mode-body-color);
	--bs-table-border-color: var(--dark-mode-divider);
}

body.dark-mode .table > :not(caption) > * > * {
	border-color: var(--dark-mode-divider);
}

body.dark-mode .card {
	--bs-card-bg: var(--dark-mode-primary-color);
	box-shadow: 0 1px 2px rgba(0, 0, 0, 0.35), 0 1px 6px rgba(0, 0, 0, 0.35);
}

/* groupsio.css dims a default panel heading in dark mode to the light text
 * colour (body.dark-mode .panel-default > .panel-heading), not the body
 * text colour. */
body.dark-mode .card > .card-header {
	color: var(--dark-mode-light-text-color);
}

/* groupsio.css's dark-mode label palette: every label takes the reverse
 * text colour (dark on its fill), primary stays white, and info drops to a
 * deeper cyan. The light-mode white-text rule for info/warning badges above
 * is !important, as are BS5's text-bg-* colours, so these are too. */
body.dark-mode .badge[class*="text-bg-"] {
	color: var(--dark-mode-reverse-text-color) !important;
}
body.dark-mode .badge.text-bg-primary {
	color: #fff !important;
}
body.dark-mode .badge.text-bg-info {
	background-color: #3da8c0 !important;
}

/* The BS5 accordion carries its own variables, so it does not follow the
 * --bs-body-* remap above and would stay a white bar on a dark page.
 * Values mirror groupsio.css's dark .panel/.panel-default .panel-heading. */
body.dark-mode .accordion-item {
	box-shadow: 0 1px 2px rgba(0, 0, 0, 0.35), 0 1px 6px rgba(0, 0, 0, 0.35);
}

body.dark-mode .accordion {
	--bs-accordion-bg: var(--dark-mode-primary-color);
	--bs-accordion-color: var(--dark-mode-text-color);
	--bs-accordion-border-color: var(--dark-mode-divider);
	--bs-accordion-btn-bg: var(--dark-mode-highlight-color);
	--bs-accordion-btn-color: var(--dark-mode-text-color);
	--bs-accordion-active-bg: var(--dark-mode-highlight-color);
	--bs-accordion-active-color: var(--dark-mode-text-color);
}

/* The chevron is a static SVG data URI, so it needs inverting rather than
 * recoloring. */
body.dark-mode .accordion-button::after {
	filter: invert(1) grayscale(100%) brightness(200%);
}

/* These toggles are anchors, and dark mode's link colors outspecify
 * .accordion-button; BS3 pinned the equivalent panel-title anchor to
 * inherit, so keep the heading text neutral here too. The hover/focus
 * pair is required separately: body.dark-mode a:hover is (0,2,2) and
 * beats a bare body.dark-mode .accordion-button. */
body.dark-mode .accordion-button,
body.dark-mode .accordion-button:hover,
body.dark-mode .accordion-button:focus {
	color: var(--bs-accordion-btn-color);
}

body.dark-mode .btn-close {
	filter: invert(1) grayscale(100%) brightness(200%);
}

/* The fileinput zoom dialog's close button carries the same name but is a
 * regular grey button beside three siblings (see .kv-zoom-actions above);
 * inverting it alone would paint one white box among the dark ones. */
body.dark-mode .kv-zoom-actions .btn-close {
	filter: none;
}

body.dark-mode .form-select {
	background-color: var(--dark-mode-input-color);
	color: var(--dark-mode-text-color);
	border-color: var(--dark-mode-divider);
	/* The chevron is a static SVG stroked in BS5's dark grey, invisible on
	 * the dark input surface. BS5's own dark theme swaps it, but keys on
	 * data-bs-theme, not body.dark-mode; groupsio.css carries the chevron
	 * in both strokes as --select-chevron for select2, so read that. */
	--bs-form-select-bg-img: var(--select-chevron);
}

/* groupsio.css's dark-mode focus for .form-control: the brand border and
 * its glow. */
body.dark-mode .form-select:focus {
	border-color: #337ab7;
	box-shadow: 0 0 5px rgba(98, 0, 238, 0.5);
}

/* BS3 made file inputs block-level, so text or a label written after one
 * (the files page's Upload Folder modal puts "Description" straight after
 * the folder picker) started a new line. BS5 leaves them inline. */
:where(input[type="file"]) {
	display: block;
}

/* BS3 buttons never wrapped their label; BS5 lets them, so a button in a
 * tight cell breaks its text onto two lines (the recurring-event modal's
 * "This And Following Events"). */
:where(.btn) {
	white-space: nowrap;
}

/* BS3's .form-horizontal right-aligned its labels from 768px up, and a
 * .col-form-label is the converted form of exactly those labels. Same 7px
 * top padding on both sides. */
@media (min-width: 768px) {
	:where(.col-form-label) {
		text-align: right;
	}
}

